window.__BOOK__ = {"title": "La IA y Mi Motor", "subtitle": "Como usar Claude y los agentes de inteligencia artificial para diagnosticar, reparar y entender cualquier vehiculo", "author": "Jose Paulino", "publisher": "Asesoria Castresana - Mieres, Asturias - 2025", "copyright": ["Copyright 2025 Jose Paulino. Todos los derechos reservados.", "Ninguna parte de esta publicacion puede ser reproducida, distribuida o transmitida en ninguna forma sin el permiso previo por escrito del autor, excepto en el caso de breves citas en resenas criticas.", "Primera edicion, 2025. Para permisos: asesoriacastresana.com", "Aviso legal: este libro tiene fines educativos e informativos. Los diagnosticos y recomendaciones son orientativos. Para diagnosticos definitivos de su vehiculo, consulte siempre a un mecanico profesional certificado."], "dedication": "Para todos los que alguna vez se quedaron tirados en la carretera sin saber que hacer. Ya no volvera a pasar.", "chapters": [{"idx": 0, "title": "Indice de Contenidos", "file": "chapters/00.json", "sections": []}, {"idx": 1, "title": "Introduccion", "file": "chapters/01.json", "sections": ["El dia que me quede tirado en la A-66", "Por que ahora es el momento", "A quien va dirigido este libro", "Que vas a conseguir"]}, {"idx": 2, "title": "CAPÍTULO 1El mecanico del futuro ya existe (y vive en tu movil)", "file": "chapters/02.json", "sections": ["El problema real de la mecanica moderna", "Que es Claude y por que no es buscar en Google", "La ventaja del que actua ahora"]}, {"idx": 3, "title": "CAPÍTULO 2Como hablarle a tu motor (el arte del prompt mecanico)", "file": "chapters/03.json", "sections": ["El mecanico que hacia las preguntas correctas", "Por que hace un ruido raro es el peor prompt del mundo", "Los 5 elementos de un prompt mecanico perfecto", "Las 5 plantillas listas para usar hoy"]}, {"idx": 4, "title": "CAPÍTULO 3El lenguaje secreto del motor: codigos OBD con IA", "file": "chapters/04.json", "sections": ["El sobre cerrado", "Que es el puerto OBD-II", "El lector OBD: que comprar y como usarlo", "El sistema de codigos OBD: como leerlos", "Los 20 codigos mas frecuentes en Espana", "Como borrar o no borrar los codigos"]}, {"idx": 5, "title": "CAPÍTULO 4Crea tu Agente IA de Motor en 10 minutos", "file": "chapters/05.json", "sections": ["El dia que Javier se convirtio en mecanico", "Que es un agente IA y como piensa", "Los 3 pasos para crear tu agente hoy", "Errores comunes y como evitarlos", "El Prompt Maestro completo"]}, {"idx": 6, "title": "CAPÍTULO 5Mantenimiento Preventivo: el Agente que Recuerda por Ti", "file": "chapters/06.json", "sections": ["El coche que nunca deberia haber fallado", "Construir el historial perfecto para tu agente", "El prompt de mantenimiento preventivo", "Las revisiones clave y cuando tocan", "El check mensual: como hacer que el agente te avise"]}, {"idx": 7, "title": "CAPÍTULO 6Diagnostico por Sintomas: Cuando el Coche te Habla sin Codigos", "file": "chapters/07.json", "sections": ["El motor que ya te esta diciendo lo que le pasa", "Los 15 sintomas mas frecuentes", "Cuando el sintoma manda al taller sin pasar por el agente"]}, {"idx": 8, "title": "CAPÍTULO 7El Agente IA para tu Taller: Atiende Clientes 24/7", "file": "chapters/08.json", "sections": ["La llamada que Marcos ya no tiene que responder", "Que puede y que no puede hacer el agente de taller", "El Prompt Maestro del Agente de Taller", "Como implementar en 3 canales", "El resumen diario automatico"]}, {"idx": 9, "title": "CAPÍTULO 8Presupuestos y Piezas: la IA que Negocia por Ti", "file": "chapters/09.json", "sections": ["El presupuesto que no cuadraba", "El prompt de evaluacion de presupuestos", "Original, OEM de marca y aftermarket", "Los 10 trabajos donde siempre debes pedir segundo presupuesto", "El truco de los trabajos encadenados"]}, {"idx": 10, "title": "CAPÍTULO 9Diesel, Gasolina y Electrico: Prompts Especializados por Motor", "file": "chapters/10.json", "sections": ["Cada motor tiene su idioma", "El motor diesel: el mas complejo y el mas mal tratado", "El motor de gasolina: del carburador al GDI", "El motor hibrido: dos sistemas, el doble de contexto", "El vehiculo electrico puro", "Tabla resumen de referencia rapida"]}, {"idx": 11, "title": "CAPÍTULO 1010 Averias Reales Resueltas con Claude", "file": "chapters/11.json", "sections": ["El valor de los casos reales", "Conclusion del capitulo"]}, {"idx": 12, "title": "CAPÍTULO 11Tu Taller Inteligente: 3 Agentes Coordinados", "file": "chapters/12.json", "sections": ["El taller que trabaja cuando tu duermes", "Los 3 agentes y lo que hace cada uno", "Arquitectura del codigo", "Instalacion paso a paso", "Comandos del bot", "El coste real del sistema"]}, {"idx": 13, "title": "CAPÍTULO 12El Futuro: Cuando el Motor Habla Solo", "file": "chapters/13.json", "sections": ["La llamada que nadie esperaba", "Las tres olas del cambio", "Por que los mecanicos que dominen la IA tendran trabajo para siempre", "El mensaje final"]}, {"idx": 14, "title": "CAPÍTULO 13Como Utilizar Claude para Todo", "file": "chapters/14.json", "sections": ["Mas alla del motor", "La estructura que lo cambia todo: ROL + CONTEXTO + TAREA + FORMATO", "Claude para tu negocio o trabajo", "Claude para tu salud y bienestar", "Claude para aprender cualquier cosa", "Los 10 prompts universales que deberias guardar", "El error mas frecuente con Claude", "El principio final"]}, {"idx": 15, "title": "Apendice A - Prompt Maestro Completo v2.0", "file": "chapters/15.json", "sections": []}, {"idx": 16, "title": "Apendice B - Los 50 Codigos OBD mas Comunes", "file": "chapters/16.json", "sections": []}, {"idx": 17, "title": "Apendice C - Recursos, Herramientas y Lectores OBD", "file": "chapters/17.json", "sections": ["Adaptadores OBD recomendados 2025", "Apps recomendadas", "Herramientas basicas para el conductor", "Webs de recambios en Espana", "Para seguir aprendiendo"]}, {"idx": 18, "title": "Apendice D - Glosario IA + Mecanica", "file": "chapters/18.json", "sections": []}]};
window.__CHAPTERS__ = [{"title": "Indice de Contenidos", "intro": [], "sections": []}, {"title": "Introduccion", "intro": [], "sections": [{"title": "El dia que me quede tirado en la A-66", "paragraphs": [{"text": "Era un martes por la manana. Ocho grados. Lluvia fina.", "list": false}, {"text": "Llevaba 40 minutos parado en el arcen de la autovia, a 30 kilometros de casa, con el capo abierto y cara de no entender absolutamente nada. El coche habia empezado a temblar, el testigo del motor se habia puesto en rojo y luego... silencio. Muerto.", "list": false}, {"text": "Llame al seguro. Grua en 90 minutos. Llame al taller. Lo miramos manana. Llame a mi cunado, que sabe de coches. Suena a juntas, tio. Eso es caro.", "list": false}, {"text": "Mientras esperaba, aburrido y mojado, abri el movil. Sin esperar nada concreto, escribi en Claude:", "list": false}, {"text": "Mi coche se ha parado de repente en la autovia. Antes de pararse temblaba mucho y el testigo del motor se puso rojo. Es un Volkswagen Golf 1.9 TDI de 2004 con 180.000 kilometros. Que puede ser?", "list": false}, {"text": "Lo que paso en los siguientes 40 segundos cambio la forma en que veo la mecanica para siempre.", "list": false}, {"text": "Claude me respondio con un diagnostico estructurado. Me pregunto si el coche habia perdido potencia antes de parar. Si habia humo. Si el testigo era fijo o parpadeante. En base a mis respuestas, me dijo: Con alta probabilidad es un fallo en el sensor de presion de aceite o perdida de presion real. Antes de arrancar de nuevo, verifica el nivel de aceite con la varilla. Si esta bajo o hay briznas metalicas, NO arranques. Si el nivel es normal, puede ser el sensor, que es una pieza de 12 euros.", "list": false}, {"text": "Comprobe el nivel. Normal. Sin virutas. El taller, dos dias despues, confirmo: sensor de presion de aceite. Pieza: 14 euros. Mano de obra: 45 minutos.", "list": false}, {"text": "Mi cunado habia dicho juntas. Eso son 800 euros.", "list": false}, {"text": "Esa tarde, tirado en el arcen con lluvia, tome una decision: iba a aprender a usar la IA para la mecanica. Y cuando lo dominara, iba a ensenarselo a todo el mundo.", "list": false}, {"text": "Este libro es el resultado de esa decision.", "list": false}], "subsections": []}, {"title": "Por que ahora es el momento", "paragraphs": [{"text": "Durante decadas, la informacion mecanica ha estado en manos de unos pocos. Los manuales tecnicos cuestan cientos de euros. La formacion especializada lleva anos. Y el resultado es una asimetria brutal: el cliente no sabe nada, el taller lo sabe todo, y eso tiene un precio que pagamos todos.", "list": false}, {"text": "La inteligencia artificial, y en concreto Claude, rompe esa asimetria de golpe.", "list": false}, {"text": "Por primera vez en la historia, cualquier persona con un movil puede acceder al equivalente de un mecanico senior con 30 anos de experiencia, disponible las 24 horas, que nunca tiene prisa, nunca te mira raro cuando haces una pregunta basica y nunca te cobra por consultar.", "list": false}], "subsections": []}, {"title": "A quien va dirigido este libro", "paragraphs": [{"text": "Este libro es para ti si eres conductor particular y has pagado una factura de taller sin entender la mitad de lo que ponia. Si eres mecanico o chapista y pierdes tiempo buscando informacion tecnica de vehiculos que no conoces bien. Si tienes un taller y recibes consultas que podrian responderse automaticamente.", "list": false}], "subsections": []}, {"title": "Que vas a conseguir", "paragraphs": [{"text": "Al llegar a la ultima pagina habras construido, paso a paso, tu propio Agente IA de Motor: un asistente especializado en tu vehiculo, que conoce su historial, que lee sus codigos de error, que diagnostica por sintomas y que esta disponible en tu movil las 24 horas.", "list": false}, {"text": "Pregunta de reflexion  La IA no sabe mas que un buen mecanico. Lo que si hace es organizar lo que sabe, hacer las preguntas correctas y darte la informacion en el momento exacto en que la necesitas. Eso, en la carretera, en el arcen, con lluvia y el coche muerto, vale mas que cualquier manual tecnico.", "list": false}], "subsections": []}]}, {"title": "CAPÍTULO 1El mecanico del futuro ya existe (y vive en tu movil)", "intro": [{"text": "Dejame contarte algo que paso en un taller de Gijon hace unos meses.", "list": false}, {"text": "Marcos lleva 22 anos como mecanico. Ha visto de todo: motores reventados, accidentes, coches que llegaron con el deposito lleno de azucar. Conoce su oficio como pocos. Pero ese lunes por la manana tenia delante un Kia Sportage 2021 con un fallo intermitente en la direccion asistida electrica que no lograba reproducir.", "list": false}, {"text": "Entonces su hijo de 19 anos, que estaba haciendo practicas en el taller, saco el movil y escribio en Claude: Kia Sportage 2021, direccion asistida electrica que falla de forma intermitente, sin codigo activo, el cliente dice que se queda dura especialmente en maniobras lentas y con el motor frio.", "list": false}, {"text": "Claude respondio en 30 segundos con un arbol de diagnostico estructurado. Primera causa probable: actualizacion de software del modulo MDPS pendiente. Segunda: sensor de par con lecturas irregulares por temperatura. Tercera: conexion del conector C204 con corrosion leve por su posicion en el paso de rueda.", "list": false}, {"text": "Marcos verifico el conector C204. Corrosion leve, exactamente como decia. Limpieza de contactos: 20 minutos. Problema resuelto.", "list": false}, {"text": "Habria tardado otro dia en llegar ahi. Y no porque no sepa mecanica. Sino porque hay demasiados modelos, demasiados sistemas, demasiada informacion. Nadie puede saberlo todo.", "list": false}], "sections": [{"title": "El problema real de la mecanica moderna", "paragraphs": [{"text": "Un mecanico de los anos 90 podia conocer a fondo los 40 o 50 modelos que circulaban habitualmente. Los motores eran mecanicos, con poca electronica. Hoy circulan mas de 400 modelos diferentes en Espana. Cada uno con su propia arquitectura electrica, su propio software de gestion, sus propios protocolos de diagnostico.", "list": false}, {"text": "Nadie puede saberlo todo. Y eso no es un fracaso del mecanico: es la realidad objetiva del sector. La inteligencia artificial si puede procesar esa cantidad de informacion. Y ponerla a tu disposicion en segundos.", "list": false}], "subsections": []}, {"title": "Que es Claude y por que no es buscar en Google", "paragraphs": [{"text": "Cuando buscas en Google ruido al frenar Golf TDI, obtienes 10 enlaces. Tienes que abrirlos, leerlos, filtrar los que son de foros de 2009, ignorar los que son publicidad de talleres, cruzar la informacion y llegar a una conclusion por tu cuenta.", "list": false}, {"text": "Claude no te da enlaces. Te hace preguntas. Es el ruido metalico o sordo? Solo al frenar o tambien al soltar el freno? En que rueda aproximadamente? Con esas respuestas, te da un diagnostico estructurado, ordenado por probabilidad, con los pasos concretos para verificar cada hipotesis.", "list": false}, {"text": "Eso no es un buscador. Es un proceso de razonamiento. Es lo que hace un mecanico con 20 anos de experiencia cuando te pregunta por el sintoma antes de abrir el capo. La diferencia es que Claude esta disponible a las 3 de la manana, no te cobra por consultar y no tiene prisa.", "list": false}], "subsections": []}, {"title": "La ventaja del que actua ahora", "paragraphs": [{"text": "La mayoria de talleres en Espana no estan usando IA de ninguna forma sistematica. La mayoria de conductores no saben que pueden diagnosticar su coche con el movil. Los primeros en dominar esto van a tener una ventaja competitiva real.", "list": false}], "subsections": [{"title": "Ejercicio practico del capitulo 1", "paragraphs": [{"text": "Abre Claude ahora mismo en claude.ai, desde el movil o el ordenador. Es gratis. Escribe esto exactamente:", "list": false}, {"text": "Actua como un mecanico senior especializado en diagnostico.", "list": false}, {"text": "Mi coche es un [marca, modelo, ano, motor].", "list": false}, {"text": "El problema que noto es [describe el sintoma mas reciente].", "list": false}, {"text": "Hazme las preguntas necesarias para afinar el diagnostico.", "list": false}, {"text": "Lee la respuesta. Observa como te pregunta antes de responder. Eso es la diferencia fundamental con cualquier buscador.", "list": false}, {"text": "Pregunta de reflexion  Cuanto tiempo llevas con el ultimo sintoma que ignoraste en tu coche? Haz la consulta ahora y comprueba en cuantos segundos tienes una orientacion que te habria costado semanas o una visita al taller.", "list": false}]}]}]}, {"title": "CAPÍTULO 2Como hablarle a tu motor (el arte del prompt mecanico)", "intro": [], "sections": [{"title": "El mecanico que hacia las preguntas correctas", "paragraphs": [{"text": "En el barrio donde creci habia un taller pequeno. El mecanico se llamaba Emilio y tenia una cualidad que tarde anos en entender: nunca abria el capo hasta que te habia hecho al menos tres preguntas.", "list": false}, {"text": "Con esas tres preguntas, Emilio ya sabia en que zona buscar. No perdia tiempo desmontando cosas innecesarias. Llegaba al problema mas rapido que cualquiera. La IA funciona exactamente igual.", "list": false}, {"text": "La calidad del diagnostico que vas a recibir de Claude depende directamente de la calidad de la informacion que le das. Un prompt vago obtiene una respuesta generica. Un prompt preciso obtiene un diagnostico que parece obra de un especialista.", "list": false}], "subsections": []}, {"title": "Por que hace un ruido raro es el peor prompt del mundo", "paragraphs": [{"text": "Imagina que le dices a un medico: me duele algo. Sin informacion, el medico no puede hacer nada util. Con la mecanica pasa exactamente lo mismo.", "list": false}, {"text": "Hace un ruido raro es tan vago que la IA solo puede darte posibilidades genericas que aplican a cualquier vehiculo del mundo.", "list": false}, {"text": "Prompt malo: Mi coche hace un ruido cuando conduzco.", "list": false}, {"text": "Resultado: lista generica de 12 posibles causas. Inutil para diagnosticar nada concreto.", "list": false}, {"text": "Prompt bueno: Mi Seat Leon 2014 1.6 TDI hace un golpeteo metalico ritmico que aparece solo cuando el motor esta frio y desaparece completamente a los 3-4 minutos de calentamiento. Suena como si algo chocara dentro del motor, mas audible en el lado derecho. El aceite esta en nivel correcto, lo cambie hace 8.000 km.", "list": false}, {"text": "Resultado: diagnostico preciso centrado en dos causas probables con pasos concretos de verificacion y estimacion de coste.", "list": false}], "subsections": []}, {"title": "Los 5 elementos de un prompt mecanico perfecto", "paragraphs": [], "subsections": [{"title": "1. El vehiculo exacto", "paragraphs": [{"text": "No solo la marca. El modelo, el ano y sobre todo el motor. El motor lo cambia todo. Un Golf 1.6 TDI y un Golf 2.0 TDI del mismo ano tienen sistemas de inyeccion completamente diferentes.", "list": false}]}, {"title": "2. Los kilometros", "paragraphs": [{"text": "El kilometraje es contexto critico. Un fallo en un motor de 30.000 km tiene causas completamente diferentes al mismo fallo en un motor de 200.000 km.", "list": false}]}, {"title": "3. El sintoma con todas sus dimensiones", "paragraphs": [{"text": "Describe el sintoma como si tuvieras que explicarselo a alguien por telefono que no puede ver ni tocar el coche.", "list": false}, {"text": "Cuando ocurre: en frio, en caliente, o siempre? Solo al acelerar, al frenar, en ralenti?", "list": true}, {"text": "Como es: metalico, sordo, silbido, golpeteo, chirrido?", "list": true}, {"text": "Donde: de que zona del coche parece venir?", "list": true}, {"text": "Que mas cambia: hay algun testigo encendido? Ha cambiado el consumo?", "list": true}]}, {"title": "4. El historial reciente relevante", "paragraphs": [{"text": "Que has tocado o cambiado ultimamente? Si tienes un ruido nuevo y hace tres dias te cambiaron las pastillas, eso es informacion critica que puede cambiar completamente el diagnostico.", "list": false}]}, {"title": "5. Lo que ya has descartado", "paragraphs": [{"text": "Ya comprobe el nivel de aceite (correcto) y el nivel de refrigerante (correcto).", "list": false}, {"text": "El testigo de temperatura no se enciende.", "list": false}]}]}, {"title": "Las 5 plantillas listas para usar hoy", "paragraphs": [], "subsections": [{"title": "Plantilla 1 - Diagnostico por ruido", "paragraphs": [{"text": "Actua como mecanico senior. Mi vehiculo es un [marca modelo ano motor].", "list": false}, {"text": "Tiene [kilometros] km.", "list": false}, {"text": "Descripcion del ruido:", "list": false}, {"text": "- Tipo: [metalico / sordo / silbido / golpeteo / chirrido]", "list": false}, {"text": "- Cuando ocurre: [en frio / en caliente / siempre / al acelerar / al frenar]", "list": false}, {"text": "- Zona aproximada: [motor / rueda delantera / debajo del coche]", "list": false}, {"text": "- Desde cuando: [hace X dias / semanas / meses]", "list": false}, {"text": "Testigos encendidos: [ninguno / motor / ABS]", "list": false}, {"text": "Historial reciente: [lo que hayas tocado o sin intervenciones recientes]", "list": false}, {"text": "Dame las causas probables ordenadas por frecuencia y los pasos", "list": false}, {"text": "para verificar cada una, de lo mas facil/barato a lo mas complejo/caro.", "list": false}]}, {"title": "Plantilla 2 - Diagnostico por sintoma de conduccion", "paragraphs": [{"text": "Actua como mecanico senior. Mi vehiculo es un [marca modelo ano motor].", "list": false}, {"text": "Tiene [kilometros] km.", "list": false}, {"text": "Sintoma que noto: [describe lo que sientes al conducir]", "list": false}, {"text": "Cuando ocurre: [siempre / a partir de X km/h / al frenar / al arrancar]", "list": false}, {"text": "Lo que ya comprobe: [nivel aceite, presion neumaticos, etc.]", "list": false}, {"text": "Testigos: [cuales o ninguno]", "list": false}, {"text": "Es seguro seguir usando el coche con normalidad?", "list": false}, {"text": "Cuales son las causas mas probables y que deberia hacer primero?", "list": false}]}, {"title": "Plantilla 3 - Interpretar codigo OBD", "paragraphs": [{"text": "Actua como mecanico experto en diagnosis electronica.", "list": false}, {"text": "Mi vehiculo: [marca modelo ano motor] con [km] km.", "list": false}, {"text": "Codigo OBD: [codigo, ej: P0420]", "list": false}, {"text": "Que significa este codigo en terminos simples?", "list": false}, {"text": "Cuales son las causas mas probables para ESTE motor en concreto?", "list": false}, {"text": "Cuales puedo verificar yo mismo?", "list": false}, {"text": "Es urgente o puede esperar?", "list": false}, {"text": "Coste estimado en Espana.", "list": false}]}, {"title": "Plantilla 4 - Revision preventiva", "paragraphs": [{"text": "Actua como mecanico de mantenimiento preventivo.", "list": false}, {"text": "Mi vehiculo: [marca modelo ano motor] con [km] km.", "list": false}, {"text": "Historial: [lista lo que recuerdes o sin historial claro]", "list": false}, {"text": "Que revisiones deberia hacer proximamente?", "list": false}, {"text": "Ordenadas por urgencia: urgente / recomendable / puede esperar.", "list": false}, {"text": "Incluye coste estimado de cada una.", "list": false}]}, {"title": "Plantilla 5 - Evaluar un presupuesto de taller", "paragraphs": [{"text": "Actua como mecanico independiente que me ayuda a evaluar un presupuesto.", "list": false}, {"text": "Mi vehiculo: [marca modelo ano motor] con [km] km.", "list": false}, {"text": "[Pega el presupuesto tal como esta]", "list": false}, {"text": "Son los precios razonables para Espana en 2025?", "list": false}, {"text": "Hay algo innecesario o que podria esperar?", "list": false}, {"text": "Falta alguna pieza asociada que normalmente se cambia a la vez?", "list": false}, {"text": "Que preguntas deberia hacerle al taller antes de aceptar?", "list": false}]}, {"title": "Ejercicio practico del capitulo 2", "paragraphs": [{"text": "Elige una de estas tres opciones:", "list": false}, {"text": "Tienes un sintoma actual: usa la plantilla que corresponda y haz la consulta ahora.", "list": true}, {"text": "No tienes ningun problema: usa la Plantilla 4 con los kilometros reales de tu coche.", "list": true}, {"text": "Eres mecanico: coge el ultimo caso complicado y describelo con la Plantilla 1.", "list": true}, {"text": "Pregunta de reflexion  Cual es la diferencia entre la respuesta que obtuviste con tu primer prompt y la que obtuviste cuando lo mejoraste con las plantillas?", "list": false}]}]}]}, {"title": "CAPÍTULO 3El lenguaje secreto del motor: codigos OBD con IA", "intro": [], "sections": [{"title": "El sobre cerrado", "paragraphs": [{"text": "Imagina que tu coche lleva anos intentando mandarte cartas. Cartas detalladas, con informacion precisa sobre lo que esta pasando dentro de cada sistema: motor, frenos, transmision, airbags, climatizacion. Cartas con codigos, fechas, contadores de fallos, valores fuera de rango.", "list": false}, {"text": "Tu nunca las has abierto. Porque el sobre tiene un candado. El candado se llama jerga tecnica. Y la llave que lo abre se llama IA.", "list": false}], "subsections": []}, {"title": "Que es el puerto OBD-II", "paragraphs": [{"text": "En 1996, la Union Europea y Estados Unidos pusieron en vigor una normativa que cambio la mecanica para siempre: todos los vehiculos de gasolina vendidos a partir de esa fecha (2001 para diesel en Europa) debian incorporar un puerto de diagnostico estandarizado bajo el salpicadero.", "list": false}, {"text": "Se llama OBD-II. Y lleva decadas registrando datos de tu coche sin que nadie te haya dicho que existe. Esta ahi ahora mismo. En tu coche. Guardando informacion.", "list": false}, {"text": "El puerto tiene un aspecto estandar en todos los vehiculos: un conector trapezoidal de 16 pines, casi siempre situado debajo del volante, a la izquierda del conductor.", "list": false}], "subsections": []}, {"title": "El lector OBD: que comprar y como usarlo", "paragraphs": [], "subsections": [{"title": "Adaptadores recomendados 2025", "paragraphs": []}, {"title": "Apps gratuitas recomendadas", "paragraphs": [{"text": "Car Scanner ELM OBD2 (iOS + Android) — La mas completa y gratuita", "list": true}, {"text": "Torque Lite (Android) — Clasica y muy fiable", "list": true}, {"text": "OBD Fusion (iOS + Android) — Excelente para iPhone", "list": true}, {"text": "Dr. Prius (iOS + Android) — Especifica para Toyota/Lexus hibridos", "list": true}]}, {"title": "Proceso completo en 3 minutos", "paragraphs": [{"text": "Conecta el adaptador al puerto OBD (debajo del volante, lado conductor)", "list": true}, {"text": "Enciende el contacto del coche (no hace falta arrancar)", "list": true}, {"text": "Abre la app, conecta con el adaptador via Bluetooth o WiFi", "list": true}, {"text": "Pulsa Leer codigos de fallo", "list": true}, {"text": "Copia los codigos que aparezcan", "list": true}, {"text": "Pegalos en tu agente IA con la Plantilla 3 del capitulo anterior", "list": true}]}]}, {"title": "El sistema de codigos OBD: como leerlos", "paragraphs": [{"text": "Todos los codigos OBD tienen exactamente 5 caracteres: una letra y cuatro numeros.", "list": false}], "subsections": [{"title": "La primera letra: el sistema", "paragraphs": []}]}, {"title": "Los 20 codigos mas frecuentes en Espana", "paragraphs": [], "subsections": [{"title": "P0300 - Fallo de encendido aleatorio (misfire multiple)", "paragraphs": [{"text": "Que significa: el motor tiene combustion irregular en varios cilindros o de forma aleatoria.", "list": false}, {"text": "Causa 1 (Alta): Bujias desgastadas con mas de 60.000 km sin cambiar", "list": true}, {"text": "Causa 2 (Alta): Bobinas de encendido con fallo intermitente", "list": true}, {"text": "Causa 3 (Media): Inyectores sucios o con fallo", "list": true}, {"text": "🟠  Urgencia media: No conducir en autovia hasta resolver. El catalizador se puede danar.", "list": false}]}, {"title": "P0301/0302/0303/0304 - Fallo de encendido en cilindro especifico", "paragraphs": [{"text": "Misfire localizado en el cilindro 1, 2, 3 o 4 respectivamente.", "list": false}, {"text": "Causa 1 (Alta): Bujia del cilindro afectado (cambiar primero, 5-8 EUR)", "list": true}, {"text": "Causa 2 (Alta): Bobina del cilindro afectado (intercambiar para confirmar)", "list": true}, {"text": "Causa 3 (Media): Inyector del cilindro afectado", "list": true}, {"text": "Truco: intercambia la bobina del cilindro que falla con la del cilindro de al lado. Si el codigo cambia al otro cilindro, la bobina esta mala.", "list": false}, {"text": "🟠  Urgencia media: Resolver en menos de 2 semanas.", "list": false}]}, {"title": "P0171 - Mezcla demasiado pobre banco 1", "paragraphs": [{"text": "El motor recibe demasiado aire o poco combustible.", "list": false}, {"text": "Fuga de vacio en el colector de admision o las mangueras", "list": true}, {"text": "Sensor MAF sucio o fallando", "list": true}, {"text": "Sonda lambda desgastada", "list": true}, {"text": "Lo que puedes hacer tu mismo: spray limpiador de carburador (3-5 EUR). Con el motor en marcha, rociar en las juntas del colector. Si el ralenti cambia, ahi esta la fuga.", "list": false}, {"text": "🟡  Urgencia baja-media: Revisar antes de la proxima ITV.", "list": false}]}, {"title": "P0420 - Eficiencia del catalizador baja", "paragraphs": [{"text": "El catalizador esta desgastado y no limpia los gases correctamente.", "list": false}, {"text": "Catalizador desgastado por la edad (frecuente en mas de 150.000 km)", "list": true}, {"text": "Sonda lambda trasera fallando (da lectura erronea)", "list": true}, {"text": "Dano en el catalizador por misfires no resueltos", "list": true}, {"text": "IMPORTANTE: antes de cambiar el catalizador (200-800 EUR), verifica primero la sonda lambda trasera (30-80 EUR).", "list": false}, {"text": "🟡  Urgencia baja: El coche funciona con normalidad. Problema de emisiones.", "list": false}]}, {"title": "P0016 - Correlacion arbol de levas / ciguenal", "paragraphs": [{"text": "Algo en la distribucion esta fuera de tiempo.", "list": false}, {"text": "Cadena de distribucion con holgura excesiva (ruido en frio)", "list": true}, {"text": "Tensor de cadena desgastado", "list": true}, {"text": "Correa de distribucion saltada (en motores con correa)", "list": true}, {"text": "🔴  ALTA si hay ruidos o misfires asociados: Llevar al taller sin demora.", "list": false}]}, {"title": "P0562 - Voltaje del sistema bajo", "paragraphs": [{"text": "El sistema electrico esta por debajo del voltaje normal (debe ser 13.5-14.5V en marcha).", "list": false}, {"text": "Bateria en mal estado (frecuente en baterias de mas de 4-5 anos)", "list": true}, {"text": "Alternador no cargando correctamente", "list": true}, {"text": "Conexiones de bateria con corrosion o flojas", "list": true}, {"text": "Verificacion basica: multimetro en bornes de bateria. Parado: 12.4-12.6V. En marcha: 13.8-14.4V. Si en marcha esta bajo 13.5V, el alternador falla.", "list": false}, {"text": "🟠  Urgencia media: Una bateria o alternador en fallo puede dejarte tirado sin aviso.", "list": false}]}, {"title": "P1000 - Monitores OBD no completados", "paragraphs": [{"text": "No es un fallo. Es un indicador de que el sistema de autodiagnostico no ha completado todos sus ciclos. Aparece despues de borrar codigos o desconectar la bateria.", "list": false}, {"text": "Que hacer: conducir el coche con normalidad durante 2-3 dias. Los monitores se completan solos.", "list": false}, {"text": "🟢  Sin urgencia: No indica ningun problema mecanico.", "list": false}]}]}, {"title": "Como borrar o no borrar los codigos", "paragraphs": [{"text": "No borres si: vas a llevar el coche al taller, no sabes que los causo, o el testigo vuelve a encenderse.", "list": false}, {"text": "Si puedes borrarlos si: hiciste la reparacion y quieres verificar que no vuelve, o fue un fallo puntual ya resuelto.", "list": false}, {"text": "Borrar un codigo no resuelve el fallo. Solo apaga el testigo temporalmente.", "list": false}, {"text": "Pregunta de reflexion  Compra un adaptador OBD esta semana (15-25 EUR). Conecta. Lee los codigos de tu coche. Si no aparece ningun codigo activo, perfecto. Si aparece alguno, tienes la guia de este capitulo para interpretarlo.", "list": false}], "subsections": []}]}, {"title": "CAPÍTULO 4Crea tu Agente IA de Motor en 10 minutos", "intro": [], "sections": [{"title": "El dia que Javier se convirtio en mecanico", "paragraphs": [{"text": "Javier tiene 34 anos, trabaja en logistica y de coches sabe lo justo. Pero lleva dos Volkswagen en casa y los ultimos tres anos ha gastado mas de 2.000 euros en talleres sin entender nunca del todo que le estaban arreglando.", "list": false}, {"text": "Hace cuatro meses, en una tarde de domingo, siguio los pasos de este capitulo. En 10 minutos tenia su Agente IA de Motor configurado. En 20 minutos habia hecho su primera consulta real sobre un ruido que llevaba semanas ignorando.", "list": false}, {"text": "El agente le hizo tres preguntas. Luego le dijo: Con alta probabilidad es el rodamiento del alternador. Coste de la pieza: 25-40 euros. Si tienes manos y un juego de llaves, puedes cambiarlo tu.", "list": false}, {"text": "Javier busco un tutorial en YouTube. Cambio el rodamiento un sabado por la manana. El ruido desaparecio.", "list": false}, {"text": "No me hice mecanico. Pero por primera vez en mi vida senti que entendia lo que pasaba en mi propio coche.", "list": false}], "subsections": []}, {"title": "Que es un agente IA y como piensa", "paragraphs": [{"text": "Un chatbot generico es como preguntarle a un desconocido por la calle. Sabe cosas, pero no sabe nada de ti, no tiene contexto y cada respuesta empieza desde cero.", "list": false}, {"text": "Un agente IA es como tener un mecanico de confianza al que conoces de hace anos. Sabe que coche tienes. Recuerda lo que le has contado. Aplica ese contexto a cada nueva consulta.", "list": false}, {"text": "La diferencia esta en el prompt maestro: el conjunto de instrucciones que le dices al agente al principio y que define quien es, que sabe y como trabaja.", "list": false}], "subsections": []}, {"title": "Los 3 pasos para crear tu agente hoy", "paragraphs": [], "subsections": [{"title": "PASO 1 - Configura el Prompt Maestro", "paragraphs": [{"text": "Toma el Prompt Maestro del Apendice A de este libro. Abrelo en cualquier editor de texto. Rellena los campos entre corchetes con los datos reales de tu vehiculo.", "list": false}, {"text": "Ejemplo de historial bien escrito:", "list": false}, {"text": "HISTORIAL CONOCIDO:", "list": false}, {"text": "- Correa distribucion: cambiada a los 120.000 km", "list": false}, {"text": "- Ultimo cambio de aceite: hace 8.000 km, aceite 5W40", "list": false}, {"text": "- Filtro de aire: cambiado hace 15.000 km", "list": false}, {"text": "- Pastillas delanteras: originales con mas de 60.000 km", "list": false}, {"text": "- Bateria: 3 anos, empieza a costar arrancar en frio", "list": false}, {"text": "- Fallo conocido: pequena fuga de aceite por retén ciguenal", "list": false}]}, {"title": "PASO 2 - Lanza el agente", "paragraphs": [{"text": "Abre claude.ai en el navegador o la app del movil. Crea un nuevo chat. Pega el prompt completo tal como esta, con tus datos ya rellenados. Pulsa enviar. Claude confirmara que ha cargado el perfil de tu vehiculo.", "list": false}]}, {"title": "PASO 3 - Primera consulta real", "paragraphs": [{"text": "No esperes a tener un problema grave. Empieza con algo pequeno:", "list": false}, {"text": "Si tienes un sintoma: Desde hace una semana noto una pequena vibracion en el volante a partir de 90 km/h.", "list": true}, {"text": "Si tienes un codigo OBD: Mi escaner marca P0171. Que significa para mi coche?", "list": true}, {"text": "Para revision preventiva: Basandote en el historial que tienes, que es lo mas urgente que deberia revisar ahora mismo?", "list": true}]}]}, {"title": "Errores comunes y como evitarlos", "paragraphs": [{"text": "Error 1: Dar sintomas vagos.", "list": true}, {"text": "El coche hace un ruido no sirve. Golpeteo metalico ritmico en frio en la parte alta del motor si sirve.", "list": false}, {"text": "Error 2: No actualizar el historial.", "list": true}, {"text": "Cada vez que tocas el coche, diselo al agente en 30 segundos.", "list": false}, {"text": "Error 3: Aceptar el diagnostico sin verificar.", "list": true}, {"text": "El agente da probabilidades, no certezas. Siempre verifica antes de comprar piezas.", "list": false}, {"text": "Error 4: Ignorar cuando dice no conduzcas.", "list": true}, {"text": "Si el agente te dice que pares, para. La IA es conservadora en seguridad por diseno.", "list": false}], "subsections": []}, {"title": "El Prompt Maestro completo", "paragraphs": [{"text": "Este es el corazon del libro. Copialo, personaliza los campos entre corchetes y pegalo en Claude.", "list": false}, {"text": "Eres MecanicIA, un agente especializado en diagnostico,", "list": false}, {"text": "mantenimiento y reparacion de vehiculos de motor.", "list": false}, {"text": "Actuas como un mecanico senior con 25 anos de experiencia", "list": false}, {"text": "en mecanica tradicional y diagnosis electronica moderna.", "list": false}, {"text": "PERFIL DEL VEHICULO:", "list": false}, {"text": "Propietario: [TU NOMBRE]", "list": false}, {"text": "Marca y modelo: [MARCA MODELO]", "list": false}, {"text": "Ano: [ANO]", "list": false}, {"text": "Motor: [EJ: 1.9 TDI 105CV]", "list": false}, {"text": "Combustible: [Diesel / Gasolina / Hibrido / Electrico]", "list": false}, {"text": "Kilometros: [KM]", "list": false}, {"text": "Uso principal: [Ciudad / Mixto / Carretera]", "list": false}, {"text": "HISTORIAL:", "list": false}, {"text": "[Lista intervenciones conocidas]", "list": false}, {"text": "CUANDO DIAGNOSTIQUES:", "list": false}, {"text": "1. Haz 2-4 preguntas clave antes de diagnosticar", "list": false}, {"text": "2. Ordena causas de mayor a menor frecuencia", "list": false}, {"text": "3. Indica verificaciones de facil/barato a complejo/caro", "list": false}, {"text": "4. Siempre indica urgencia y si es seguro conducir", "list": false}, {"text": "5. Da estimacion de coste en Espana", "list": false}, {"text": "FORMATO:", "list": false}, {"text": "DIAGNOSTICO PRELIMINAR", "list": false}, {"text": "NECESITO SABER (si hace falta)", "list": false}, {"text": "CAUSAS PROBABLES (de mas a menos probable)", "list": false}, {"text": "PASOS A SEGUIR", "list": false}, {"text": "URGENCIA: verde/naranja/rojo", "list": false}, {"text": "COSTE ESTIMADO", "list": false}, {"text": "Pregunta de reflexion  Cual es la ultima factura de taller que pagaste sin entender del todo que te arreglaron? Que habrias preguntado al agente antes de ir?", "list": false}], "subsections": []}]}, {"title": "CAPÍTULO 5Mantenimiento Preventivo: el Agente que Recuerda por Ti", "intro": [], "sections": [{"title": "El coche que nunca deberia haber fallado", "paragraphs": [{"text": "Sandra tiene un Renault Clio 2016. A los 95.000 kilometros, una manana de enero, el coche se paro en medio de la rotonda de salida de su trabajo. La correa de distribucion habia saltado.", "list": false}, {"text": "Dano en el motor: 1.800 euros. Cuando tocaba cambiar la correa? A los 90.000 kilometros o cada 5 anos. Sandra tenia 95.000 km y 6 anos. Llego a las dos condiciones el mismo mes. Nadie le habia avisado.", "list": false}, {"text": "Eso se acabo con la IA.", "list": false}], "subsections": []}, {"title": "Construir el historial perfecto para tu agente", "paragraphs": [{"text": "HISTORIAL DEL VEHICULO - [Marca Modelo Ano Motor]", "list": false}, {"text": "Kilometros actuales: [X]", "list": false}, {"text": "Fecha: [DD/MM/AAAA]", "list": false}, {"text": "INTERVENCIONES CONOCIDAS:", "list": false}, {"text": "- Cambio de aceite: [km del ultimo]", "list": false}, {"text": "- Correa/cadena de distribucion: [km o sin historial]", "list": false}, {"text": "- Filtro de aire: [km o no recuerdo]", "list": false}, {"text": "- Pastillas delanteras: [km o no recuerdo]", "list": false}, {"text": "- Pastillas traseras: [km o no recuerdo]", "list": false}, {"text": "- Neumaticos: [cuando los pusiste]", "list": false}, {"text": "- Bateria: [cuantos anos tiene]", "list": false}, {"text": "- Liquido de frenos: [ano del ultimo cambio]", "list": false}], "subsections": []}, {"title": "El prompt de mantenimiento preventivo", "paragraphs": [{"text": "Actua como mecanico especializado en mantenimiento preventivo.", "list": false}, {"text": "Mi vehiculo: [marca modelo ano motor].", "list": false}, {"text": "Kilometros actuales: [X km]", "list": false}, {"text": "Fecha: [DD/MM/AAAA]", "list": false}, {"text": "HISTORIAL COMPLETO:", "list": false}, {"text": "[Pega aqui tu historial]", "list": false}, {"text": "Dime:", "list": false}, {"text": "1. Que revisiones son URGENTES ahora mismo?", "list": false}, {"text": "2. Que revisiones son PROXIMAS en los siguientes 10.000 km o 6 meses?", "list": false}, {"text": "3. Que puedo PLANIFICAR para mas adelante?", "list": false}, {"text": "4. Hay alguna revision critica sin registro dado el kilometraje?", "list": false}, {"text": "Para cada punto: que se revisa, por que es importante,", "list": false}, {"text": "coste estimado en Espana, consecuencia de ignorarlo.", "list": false}], "subsections": []}, {"title": "Las revisiones clave y cuando tocan", "paragraphs": [], "subsections": [{"title": "Aceite y filtro de aceite", "paragraphs": [{"text": "Cada 10.000-15.000 km en gasolina con aceite sintetico. Cada 8.000-10.000 km en diesel. Nunca mas de 1 ano aunque no llegues a los kilometros.", "list": false}, {"text": "Si lo ignoras: desgaste acelerado de todos los componentes. En motores modernos con distribucion variable, puede generar los codigos P0011/P0021.", "list": false}, {"text": "Coste: 40-90 EUR segun tipo de aceite.", "list": false}]}, {"title": "Correa de distribucion (la mas critica)", "paragraphs": [{"text": "La correa de distribucion sincroniza el movimiento del ciguenal con los arboles de levas. Si se rompe en motores de interferencia, las valvulas chocan con los pistones. Dano catastrofico: 2.000-5.000 EUR.", "list": false}, {"text": "Regla de oro: si no sabes cuando se cambio la ultima correa, considera que no se ha cambiado nunca. El coste de revisar es cero. El coste de ignorarlo puede ser el motor.", "list": false}]}, {"title": "Pastillas y discos de freno", "paragraphs": [{"text": "Pastillas: entre 30.000 y 60.000 km segun el uso. Discos: 60.000-100.000 km en condiciones normales.", "list": false}, {"text": "Coste: 80-160 EUR por eje (pastillas + mano de obra). 150-320 EUR si se cambian tambien los discos.", "list": false}]}, {"title": "Bateria", "paragraphs": [{"text": "Las baterias convencionales duran entre 4 y 6 anos. Las de arranque-parada (start/stop) entre 3 y 5 anos.", "list": false}, {"text": "Senales de alerta: arranque mas lento de lo normal en frio, testigo de bateria intermitente, codigo P0562.", "list": false}]}]}, {"title": "El check mensual: como hacer que el agente te avise", "paragraphs": [{"text": "Han pasado [X] meses desde la ultima consulta.", "list": false}, {"text": "Kilometros actuales: [X]", "list": false}, {"text": "Hay algo que haya llegado o este proximo a su intervalo?", "list": false}, {"text": "Algun cambio estacional que deba considerar?", "list": false}, {"text": "[Si has notado algo nuevo: describelo aqui]", "list": false}, {"text": "Pregunta de reflexion  Cuanto dinero has gastado en averias que podrian haberse evitado con una revision preventiva? Eso es exactamente lo que el agente va a evitarte de ahora en adelante.", "list": false}], "subsections": []}]}, {"title": "CAPÍTULO 6Diagnostico por Sintomas: Cuando el Coche te Habla sin Codigos", "intro": [], "sections": [{"title": "El motor que ya te esta diciendo lo que le pasa", "paragraphs": [{"text": "El sistema OBD es extraordinario pero tiene un limite importante: solo genera codigos cuando un sensor detecta que algo esta fuera de rango. Hay toda una categoria de fallos mecanicos que no generan ningun codigo porque ningun sensor los detecta directamente.", "list": false}, {"text": "Un rodamiento de rueda que empieza a desgastarse no genera codigo OBD. Lo que genera es un zumbido que aumenta con la velocidad. Un amortiguador que esta perdiendo efectividad no tiene sensor dedicado. Estos sintomas son en realidad mas valiosos porque aparecen antes.", "list": false}], "subsections": []}, {"title": "Los 15 sintomas mas frecuentes", "paragraphs": [], "subsections": [{"title": "SINTOMA 1 - Ruido metalico en frio que desaparece al calentar", "paragraphs": [{"text": "Como suena: golpeteo o traqueteo ritmico, sincronizado con las RPM del motor. Aparece en los primeros minutos de arranque y desaparece gradualmente.", "list": false}, {"text": "Escucho un golpeteo metalico ritmico durante los primeros [X] minutos", "list": false}, {"text": "despues de arrancar en frio. Desaparece completamente cuando el motor", "list": false}, {"text": "alcanza temperatura. El sonido parece venir de la parte alta del motor,", "list": false}, {"text": "lado [izquierdo/derecho]. Las RPM en ralenti son normales.", "list": false}, {"text": "Para motores con cadena: holgura en el tensor de cadena", "list": true}, {"text": "Para motores con distribucion variable (VVTI): hidraulicos de valvulas", "list": true}, {"text": "🟠  Media: Si el sonido ha empeorado con el tiempo, ir al taller esta semana.", "list": false}]}, {"title": "SINTOMA 2 - Vibracion en el volante a velocidades concretas", "paragraphs": [{"text": "Noto vibracion en el volante que aparece entre [X] y [Y] km/h", "list": false}, {"text": "y desaparece fuera de ese rango. [Hace/No hace] X semanas cambie", "list": false}, {"text": "los neumaticos. El pedal de freno [vibra / no vibra].", "list": false}, {"text": "60-90 km/h: desequilibrio de ruedas (solucion barata: equilibrado)", "list": true}, {"text": "90-120 km/h: desequilibrio ruedas traseras o rotula con holgura", "list": true}, {"text": "Solo al frenar: discos de freno deformados", "list": true}]}, {"title": "SINTOMA 3 - Coche que tira hacia un lado", "paragraphs": [{"text": "Tira siempre: geometria fuera de ajuste (alineacion, 35-60 EUR)", "list": true}, {"text": "Solo al frenar: pastilla de freno agarrotada en un lado", "list": true}, {"text": "Solo al acelerar en primera: par de reaccion del motor (normal)", "list": true}]}, {"title": "SINTOMA 4 - Humo del escape", "paragraphs": [{"text": "Humo blanco denso persistente: liquido refrigerante entrando al motor. Junta de culata. URGENTE.", "list": false}, {"text": "🔴  ALTA: Para el coche. No sigas conduciendo.", "list": false}, {"text": "Humo blanco fino al arrancar en frio: condensacion normal. No requiere accion.", "list": false}, {"text": "Humo azul: aceite quemandose. Sellos de valvulas o segmentos del piston.", "list": false}, {"text": "Humo negro (gasolina): mezcla demasiado rica. Inyector atascado, sensor MAF.", "list": false}, {"text": "Humo negro denso (diesel): inyectores desgastados, turbo en mal estado, EGR atascado.", "list": false}]}, {"title": "SINTOMA 5 - Pedal de freno esponjoso o que baja al fondo", "paragraphs": [{"text": "Este es uno de los sintomas que requieren atencion inmediata.", "list": false}, {"text": "Pedal esponjoso: aire en el circuito de frenos. Sangrar los frenos.", "list": false}, {"text": "Pedal que baja lentamente: fuga interna en el cilindro maestro.", "list": false}, {"text": "🔴  ALTA: Si tienes dudas con los frenos, ir al taller hoy.", "list": false}]}, {"title": "SINTOMA 6 - Zumbido que aumenta con la velocidad", "paragraphs": [{"text": "Escucho un zumbido constante que aumenta con la velocidad del coche", "list": false}, {"text": "(no con las RPM del motor). El zumbido [cambia / no cambia] al girar", "list": false}, {"text": "ligeramente el volante. Parece venir de la rueda [delantera/trasera] [izquierda/derecha].", "list": false}, {"text": "Truco del volante: si al girar suavemente a la izquierda el zumbido aumenta, el rodamiento malo esta en la rueda delantera derecha. Y viceversa. Coste: 90-250 EUR segun rueda.", "list": false}]}, {"title": "SINTOMA 7 - Consumo disparado de forma repentina", "paragraphs": [{"text": "Gasolina con aumento brusco: sonda lambda muerta, inyectores sucios", "list": true}, {"text": "Diesel con aumento gradual: inyectores desgastados, EGR atascado", "list": true}, {"text": "Cualquier tipo: neumaticos con presion baja (revisar primero, es gratis)", "list": true}]}, {"title": "SINTOMA 8 - Dificultad de arranque en frio", "paragraphs": [{"text": "Gasolina: bujias desgastadas (la causa mas frecuente)", "list": true}, {"text": "Diesel: bujias de precalentamiento desgastadas", "list": true}, {"text": "Cualquier tipo: bateria debil (primer diagnostico siempre)", "list": true}]}, {"title": "SINTOMA 9 - Olor a quemado", "paragraphs": [{"text": "Aceite quemado despues de conducir: fuga de aceite cayendo sobre el escape o turbo.", "list": false}, {"text": "Goma quemada: correa de accesorios rozando o deslizando.", "list": false}, {"text": "Olor dulzon a anticongelante: fuga de liquido refrigerante.", "list": false}, {"text": "🔴  ALTA si es dulzon o plastico: Revisar visualmente inmediatamente.", "list": false}]}, {"title": "SINTOMA 10 - Golpe o traqueteo al pasar por baches", "paragraphs": [{"text": "Golpe metalico seco en baches pequenos: bieleta de barra estabilizadora. Pieza 15-25 EUR.", "list": false}, {"text": "Golpe sordo en baches grandes: amortiguador agotado.", "list": false}, {"text": "Chirrido metalico: silentblocks del triangulo de suspension.", "list": false}]}, {"title": "SINTOMA 11 - Motor que falla en ralenti", "paragraphs": [{"text": "La causa mas frecuente y barata: valvula IAC o mariposa sucia con carbonilla. Limpieza con spray especifico: 5-10 EUR de producto, 20-30 minutos de trabajo.", "list": false}]}, {"title": "SINTOMA 12 - Perdida de potencia progresiva", "paragraphs": [{"text": "Motores turbo diesel/gasolina: el turbo es la primera sospecha", "list": true}, {"text": "Motores aspiracion natural: catalizador obstruido, filtro de aire saturado", "list": true}]}, {"title": "SINTOMA 13 - Aceite que baja mas de lo normal", "paragraphs": [{"text": "Un consumo de hasta 0.5L cada 1.000 km es dentro de especificacion en muchos motores modernos. Por encima de ese umbral hay que investigar.", "list": false}]}, {"title": "SINTOMA 14 - Temperatura que sube mas de lo normal", "paragraphs": [{"text": "🔴  ATENCION INMEDIATA: Protocolo si la temperatura llega a la zona roja:", "list": false}, {"text": "Apaga el aire acondicionado", "list": true}, {"text": "Pon la calefaccion al maximo (extrae calor del motor)", "list": true}, {"text": "Si sigue subiendo, para en el arcen con seguridad", "list": true}, {"text": "NO abras el tapon del radiador en caliente", "list": true}, {"text": "Espera a que el motor enfrie completamente antes de revisar", "list": true}]}, {"title": "SINTOMA 15 - Cambios de marcha que no van suaves", "paragraphs": [{"text": "Manual - cambio duro: aceite de caja desgastado o horquilla del embrague.", "list": false}, {"text": "Manual - vibracion al embragar: disco de embrague con el amortiguador de torsion desgastado.", "list": false}, {"text": "Automatica - cambios bruscos: aceite ATF sucio o bajo nivel.", "list": false}]}]}, {"title": "Cuando el sintoma manda al taller sin pasar por el agente", "paragraphs": [{"text": "Hay sintomas que no necesitan diagnostico IA previo. Necesitan ir al taller directamente:", "list": false}, {"text": "Humo blanco denso y persistente del escape", "list": true}, {"text": "Temperatura en zona roja", "list": true}, {"text": "Perdida de frenos (pedal va al fondo sin frenar)", "list": true}, {"text": "Olor fuerte a quemado con posible fuente electrica", "list": true}, {"text": "Golpe fuerte seguido de perdida de direccion o control", "list": true}, {"text": "Pregunta de reflexion  Sientate en tu coche, arranque, y durante 3 minutos escucha, siente y huele con atencion. Hay algun sonido que hayas normalizado y que no era asi hace un ano?", "list": false}], "subsections": []}]}, {"title": "CAPÍTULO 7El Agente IA para tu Taller: Atiende Clientes 24/7", "intro": [], "sections": [{"title": "La llamada que Marcos ya no tiene que responder", "paragraphs": [{"text": "Son las 22:15 de un martes. Marcos esta cenando. Su movil vibra. Numero desconocido. Lo coge porque siempre lo coge, lleva 18 anos cogiendo todas las llamadas porque en el taller cada cliente cuenta.", "list": false}, {"text": "El cliente pregunta si el ruido que tiene es grave. Marcos aparta el plato, escucha, hace preguntas, tranquiliza al cliente, le dice que pase manana. Cuelga. La cena esta fria.", "list": false}, {"text": "Multiplicado por 52 semanas, son entre 150 y 200 interrupciones fuera de horario al ano. El Agente de Taller resuelve eso. Completamente. Sin que Marcos tenga que estar.", "list": false}], "subsections": []}, {"title": "Que puede y que no puede hacer el agente de taller", "paragraphs": [], "subsections": [{"title": "El agente SI puede", "paragraphs": [{"text": "Responder consultas de sintomas basicos a cualquier hora", "list": true}, {"text": "Dar orientacion de urgencia (puedo seguir conduciendo o no?)", "list": true}, {"text": "Informar sobre servicios del taller, precios orientativos y horarios", "list": true}, {"text": "Recoger nombre, vehiculo y problema para el mecanico", "list": true}, {"text": "Hacer seguimiento post-servicio", "list": true}]}, {"title": "El agente NO puede", "paragraphs": [{"text": "Dar diagnosticos definitivos sin inspeccion fisica", "list": true}, {"text": "Comprometer precios exactos sin ver el vehiculo", "list": true}, {"text": "Prometer disponibilidad sin confirmar con el taller", "list": true}]}]}, {"title": "El Prompt Maestro del Agente de Taller", "paragraphs": [{"text": "Eres el asistente virtual del [NOMBRE DEL TALLER].", "list": false}, {"text": "DATOS DEL TALLER:", "list": false}, {"text": "Nombre: [NOMBRE]", "list": false}, {"text": "Direccion: [DIRECCION]", "list": false}, {"text": "Telefono: [TELEFONO]", "list": false}, {"text": "Horario: [HORARIO]", "list": false}, {"text": "Especialidades: [lista]", "list": false}, {"text": "PRECIOS ORIENTATIVOS:", "list": false}, {"text": "- Diagnostico electronico: 40-60 EUR", "list": false}, {"text": "- Cambio de aceite + filtro turismo: 50-90 EUR", "list": false}, {"text": "- Pastillas freno eje delantero: 90-160 EUR", "list": false}, {"text": "- Discos + pastillas eje: 180-320 EUR", "list": false}, {"text": "- Pre-ITV: 30-45 EUR", "list": false}, {"text": "TU FORMA DE TRABAJAR:", "list": false}, {"text": "PASO 1: Preguntar nombre del cliente", "list": false}, {"text": "PASO 2: Preguntar marca, modelo, ano del coche", "list": false}, {"text": "PASO 3: Preguntar el problema o servicio necesario", "list": false}, {"text": "PASO 4: Dar orientacion basica y precio orientativo", "list": false}, {"text": "PASO 5: Capturar nombre, telefono, vehiculo y problema", "list": false}, {"text": "FINAL: Le pasare estos datos al equipo. [Nombre mecanico]", "list": false}, {"text": "le contactara en horario de apertura para confirmar.", "list": false}, {"text": "PROTOCOLO URGENCIAS - Si describe humo, temperatura roja,", "list": false}, {"text": "frenos que no responden, olor electrico:", "list": false}, {"text": "Decir exactamente: Por lo que describes, no te recomiendo", "list": false}, {"text": "seguir conduciendo. Llamanos directamente al [TELEFONO].", "list": false}, {"text": "TONO: Cercano, honesto, profesional. Maximo 4 lineas por mensaje.", "list": false}], "subsections": []}, {"title": "Como implementar en 3 canales", "paragraphs": [], "subsections": [{"title": "Canal 1 - Telegram (el mas facil, listo en 1 hora)", "paragraphs": [{"text": "Usando el codigo del Capitulo 11, tienes el bot funcionando con este prompt en lugar del prompt de diagnostico tecnico.", "list": false}]}, {"title": "Canal 2 - WhatsApp Business (el mas alcance)", "paragraphs": [{"text": "WhatsApp tiene 30 millones de usuarios activos en Espana. El codigo del Capitulo 11 incluye el bot de WhatsApp ya configurado para taller.", "list": false}]}, {"title": "Canal 3 - Web chat", "paragraphs": [{"text": "Si tienes web del taller, puedes incrustar un chat inteligente. Requiere un widget (Crisp, Tidio) conectado a tu servidor. Configuracion: 2-4 horas con conocimientos tecnicos basicos.", "list": false}]}]}, {"title": "El resumen diario automatico", "paragraphs": [{"text": "Revisa todas las conversaciones de las ultimas [X] horas.", "list": false}, {"text": "Genera un resumen con:", "list": false}, {"text": "URGENCIAS: [Clientes que necesitan atencion hoy]", "list": false}, {"text": "CITAS SOLICITADAS: [Nombre, vehiculo, preferencia horaria]", "list": false}, {"text": "CONSULTAS INFORMATIVAS: [Resumen de cada consulta resuelta]", "list": false}, {"text": "SEGUIMIENTOS PENDIENTES: [Clientes que esperan respuesta]", "list": false}, {"text": "Pregunta de reflexion  Cuantas consultas fuera de horario recibes a la semana? Multiplica por 52. Ese es el tiempo que el agente te devuelve cada ano.", "list": false}], "subsections": []}]}, {"title": "CAPÍTULO 8Presupuestos y Piezas: la IA que Negocia por Ti", "intro": [], "sections": [{"title": "El presupuesto que no cuadraba", "paragraphs": [{"text": "Miguel recibio un presupuesto de su taller habitual para cambiar el embrague de su Volkswagen Caddy 2.0 TDI de 2015: 1.240 euros. El mecanico le dijo que era lo que habia.", "list": false}, {"text": "Miguel no sabia si era caro o barato. Antes de aceptar, le paso el presupuesto al agente:", "list": false}, {"text": "Mi VW Caddy 2.0 TDI 2015 con 148.000 km. Kit de embrague 620 EUR, volante bimasa 480 EUR, mano de obra 140 EUR. Total 1.240 EUR. Es razonable?", "list": false}, {"text": "El agente le respondio en 30 segundos: el kit de embrague para ese motor en recambio de calidad media esta entre 180 y 320 EUR. El volante bimasa entre 280 y 450 EUR. La mano de obra para ese cambio son 3-4 horas a 50-70 EUR/hora. El total razonable estaria entre 750 y 1.050 EUR.", "list": false}, {"text": "Miguel llamo al taller. Pregunto que marcas eran las piezas. El mecanico reconocio que usaba las del fabricante pero que podia usar LUK, igualmente fiables. Precio final: 980 euros. 260 euros menos por una pregunta de 30 segundos.", "list": false}], "subsections": []}, {"title": "El prompt de evaluacion de presupuestos", "paragraphs": [{"text": "Actua como mecanico independiente que me ayuda a evaluar un presupuesto.", "list": false}, {"text": "Sin conflicto de interes con ningun taller.", "list": false}, {"text": "Mi vehiculo: [marca modelo ano motor] con [km] km. Zona: Espana.", "list": false}, {"text": "Presupuesto recibido:", "list": false}, {"text": "[Pega aqui el presupuesto completo]", "list": false}, {"text": "1. El precio de cada pieza es razonable en Espana 2025?", "list": false}, {"text": "2. Las horas de mano de obra son coherentes con el trabajo?", "list": false}, {"text": "3. Hay algo innecesario o que pueda esperar?", "list": false}, {"text": "4. Falta alguna pieza que normalmente se cambia a la vez?", "list": false}, {"text": "5. Que preguntas deberia hacer al taller antes de aceptar?", "list": false}, {"text": "6. Cual seria el rango de precio razonable para este trabajo?", "list": false}], "subsections": []}, {"title": "Original, OEM de marca y aftermarket", "paragraphs": [], "subsections": [{"title": "Piezas originales (OEM del fabricante del coche)", "paragraphs": [{"text": "Son las mas caras. Cuando merece la pena: piezas de seguridad critica en coches en garantia. Para piezas mecanicas estandar, no es necesario.", "list": false}]}, {"title": "Piezas OEM de marca (LUK, Sachs, Bosch, Brembo...)", "paragraphs": [{"text": "Son las mismas piezas que fabrica el proveedor del fabricante, vendidas bajo su propia marca. Un embrague LUK para un VW Golf es exactamente la misma pieza que el original VW, porque LUK es quien los fabrica para VW. Cuestan entre 20-40% menos. Para la mayoria de trabajos, esta es la opcion optima.", "list": false}]}, {"title": "Piezas aftermarket genericas", "paragraphs": [{"text": "Calidad muy variable. Para piezas de bajo coste (filtros, escobillas) suelen ser validas. Para piezas de seguridad o alta exigencia mecanica, el ahorro puede salir caro.", "list": false}]}]}, {"title": "Los 10 trabajos donde siempre debes pedir segundo presupuesto", "paragraphs": [], "subsections": []}, {"title": "El truco de los trabajos encadenados", "paragraphs": [{"text": "Uno de los errores mas caros en mecanica es hacer un trabajo sin aprovechar para cambiar piezas relacionadas.", "list": false}, {"text": "Si cambias la correa de distribucion, cambia tambien tensor y polea. Kit completo: 50-80 EUR mas. Volver a abrir el mismo motor por el tensor: doble en mano de obra.", "list": true}, {"text": "Si cambias el embrague, revisa el volante bimasa mientras estan desmontados.", "list": true}, {"text": "Si cambias los amortiguadores traseros, cambia los silentblocks del mismo eje si tienen mas de 100.000 km.", "list": true}, {"text": "Voy a cambiar [trabajo] en mi [coche + km].", "list": false}, {"text": "Que otras piezas de la misma zona deberia revisar o cambiar", "list": false}, {"text": "aprovechando que ya esta desmontada?", "list": false}, {"text": "Que seria negligente ignorar mientras estamos ahi?", "list": false}, {"text": "Cuanto aniade al presupuesto vs. cuanto ahorraria si", "list": false}, {"text": "tuviera que volver a hacer ese trabajo por separado?", "list": false}, {"text": "Pregunta de reflexion  Cuanto dinero has gastado en los ultimos 5 anos en reparaciones de coche? Cuanto habrias ahorrado si hubieras podido evaluar cada presupuesto antes de firmarlo?", "list": false}], "subsections": []}]}, {"title": "CAPÍTULO 9Diesel, Gasolina y Electrico: Prompts Especializados por Motor", "intro": [], "sections": [{"title": "Cada motor tiene su idioma", "paragraphs": [{"text": "Un prompt generico de mecanica funciona para el 80% de las consultas. Pero hay un 20% donde el tipo de motor lo cambia todo: el diesel con su sistema de inyeccion de alta presion y sus filtros de particulas no tiene nada que ver con el gasolina de aspiracion natural.", "list": false}], "subsections": []}, {"title": "El motor diesel: el mas complejo y el mas mal tratado", "paragraphs": [], "subsections": [{"title": "Los 4 sistemas criticos del diesel moderno", "paragraphs": [{"text": "Sistema de inyeccion common rail: presiones de 1.600 a 2.500 bares. Los inyectores son piezoelectricos con tolerancias de micras. Es el sistema mas caro de reparar.", "list": false}, {"text": "Filtro de particulas (DPF/FAP): captura el hollin y lo quema periodicamente. El problema: conductores urbanos que nunca dejan regenerar.", "list": false}, {"text": "Valvula EGR: recircula gases de escape. Con el tiempo la carbonilla la obstruye hasta dejarla pegada.", "list": false}, {"text": "Turbo de geometria variable (VGT): ajusta las paletas segun las RPM. Las paletas pueden pegarse con carbonilla.", "list": false}]}, {"title": "Prompt Maestro para motor diesel", "paragraphs": [{"text": "Eres un mecanico especializado en motores diesel", "list": false}, {"text": "de inyeccion directa common rail.", "list": false}, {"text": "VEHICULO:", "list": false}, {"text": "Marca/Modelo/Ano: [datos]", "list": false}, {"text": "Motor: [ej: 2.0 TDI 140cv, 1.9 dCi 110cv]", "list": false}, {"text": "Kilometros: [X]", "list": false}, {"text": "Uso principal: [urbano / mixto / carretera]", "list": false}, {"text": "HISTORIAL DIESEL:", "list": false}, {"text": "- Ultimo cambio de aceite: [cuando y viscosidad]", "list": false}, {"text": "- Estado DPF: [regenerado / obstruido / desconocido]", "list": false}, {"text": "- Valvula EGR: [limpiada / sustituida / sin historial]", "list": false}, {"text": "- Filtro de combustible: [km o desconocido]", "list": false}, {"text": "Ten en cuenta siempre:", "list": false}, {"text": "- Uso urbano con trayectos cortos = alto riesgo DPF y EGR", "list": false}, {"text": "- Antes de recomendar cambio de DPF, verifica regeneracion forzada", "list": false}, {"text": "- El aceite debe tener la especificacion correcta para DPF", "list": false}, {"text": "- Para codigos de inyeccion, diferencia inyector vs rail/bomba", "list": false}]}, {"title": "Prompts especificos diesel", "paragraphs": [{"text": "Para el DPF: Mi diesel + uso urbano tiene el testigo del DPF encendido. Cuales son los pasos para una regeneracion activa antes de ir al taller?", "list": false}, {"text": "Para el EGR: Codigo P0401 y ralenti inestable. Como limpio la EGR sin desmontarla? Cuando ya no sirve y hay que sustituir?", "list": false}, {"text": "Para inyectores: Ruido de maquina de coser a altas RPM. Cuando conviene lavar vs rectificar vs sustituir los inyectores?", "list": false}, {"text": "Para turbo VGT: Modo de emergencia intermitente con codigo de presion de sobrealimentacion. Como distingo si es el actuador, las paletas pegadas o dano mecanico?", "list": false}]}]}, {"title": "El motor de gasolina: del carburador al GDI", "paragraphs": [], "subsections": [{"title": "El problema especifico del GDI (inyeccion directa de gasolina)", "paragraphs": [{"text": "En el GDI, el combustible se inyecta directamente en el cilindro. La ventaja es eficiencia. El inconveniente: los puertos de admision y las valvulas se llenan de depositos de carbono porque el combustible ya no los limpia al pasar.", "list": false}, {"text": "Sintomas: ralenti irregular, tirones al acelerar en frio, perdida de potencia a partir de 80.000-100.000 km.", "list": false}, {"text": "Solucion: limpieza de valvulas por walnut blasting. Un proceso especifico de este tipo de motor.", "list": false}]}, {"title": "Prompt Maestro para motor gasolina", "paragraphs": [{"text": "Eres un mecanico especializado en motores de gasolina,", "list": false}, {"text": "incluyendo turbos de pequena cilindrada con inyeccion directa (GDI/TSI).", "list": false}, {"text": "VEHICULO:", "list": false}, {"text": "Marca/Modelo/Ano: [datos]", "list": false}, {"text": "Motor: [ej: 1.4 TSI 125cv, 1.0 Ecoboost 100cv]", "list": false}, {"text": "Tipo de inyeccion: [directa GDI / indirecta / mixta]", "list": false}, {"text": "Tiene turbo: [si/no]", "list": false}, {"text": "Kilometros: [X]", "list": false}, {"text": "Para GDI con sintomas de ralenti/tirones, considera", "list": false}, {"text": "sempre los depositos de carbono como causa probable.", "list": false}, {"text": "Para turbos gasolina, el aceite y su calidad son primer punto.", "list": false}, {"text": "Bujias y bobinas primero, siempre, antes de buscar causas", "list": false}, {"text": "mas profundas en misfires de gasolina.", "list": false}]}]}, {"title": "El motor hibrido: dos sistemas, el doble de contexto", "paragraphs": [], "subsections": [{"title": "Los dos tipos de hibrido mas comunes en Espana", "paragraphs": [{"text": "Hibrido convencional (HEV): Toyota Prius, Honda Jazz. La bateria se carga solo por regeneracion. No se enchufa.", "list": false}, {"text": "Hibrido enchufable (PHEV): Mitsubishi Outlander, VW Golf GTE. La bateria puede cargarse desde la red.", "list": false}]}, {"title": "Prompt Maestro para vehiculo hibrido", "paragraphs": [{"text": "Eres un mecanico especializado en vehiculos hibridos,", "list": false}, {"text": "con conocimiento del sistema de combustion Y del sistema", "list": false}, {"text": "electrico de alta tension.", "list": false}, {"text": "VEHICULO:", "list": false}, {"text": "Marca/Modelo/Ano: [datos]", "list": false}, {"text": "Tipo de hibrido: [HEV / PHEV / mild hybrid]", "list": false}, {"text": "Kilometros: [X]", "list": false}, {"text": "Bateria de traccion: [anos / % capacidad o desconocido]", "list": false}, {"text": "CONTEXTO CRITICO:", "list": false}, {"text": "- NUNCA toques el sistema electrico de alta tension", "list": false}, {"text": "sin formacion especifica. Los cables naranjas matan.", "list": false}, {"text": "- Para muchas intervenciones, el sistema electrico debe", "list": false}, {"text": "desactivarse antes de trabajar.", "list": false}, {"text": "- El motor de combustion en hibrido tiene intervalos", "list": false}, {"text": "de mantenimiento DIFERENTES a la version no hibrida.", "list": false}, {"text": "- La bateria de traccion se degrada progresivamente", "list": false}, {"text": "con sintomas detectables antes del fallo total.", "list": false}]}]}, {"title": "El vehiculo electrico puro", "paragraphs": [], "subsections": [{"title": "Prompt Maestro para electrico", "paragraphs": [{"text": "Eres especialista en vehiculos electricos (BEV)", "list": false}, {"text": "con conocimiento en baterias de traccion,", "list": false}, {"text": "sistemas de carga y electronica de potencia.", "list": false}, {"text": "VEHICULO:", "list": false}, {"text": "Marca/Modelo/Ano: [datos]", "list": false}, {"text": "Bateria: [kWh si lo sabes]", "list": false}, {"text": "Kilometros: [X]", "list": false}, {"text": "Carga habitual: [AC lenta / wallbox / cargadores rapidos DC]", "list": false}, {"text": "CONTEXTO BEV:", "list": false}, {"text": "- No hay aceite de motor, bujias, distribucion ni escape.", "list": false}, {"text": "- La bateria es el activo mas importante.", "list": false}, {"text": "- Los frenos duran mas por frenada regenerativa pero", "list": false}, {"text": "pueden agarrotarse por falta de uso fisico.", "list": false}, {"text": "- Para problemas de alta tension: taller especializado.", "list": false}]}]}, {"title": "Tabla resumen de referencia rapida", "paragraphs": [{"text": "Pregunta de reflexion  Estas usando el aceite correcto para tu tipo de motor? El aceite equivocado en un motor moderno es uno de los danos mas frecuentes y mas silenciosos de la mecanica actual.", "list": false}], "subsections": []}]}, {"title": "CAPÍTULO 1010 Averias Reales Resueltas con Claude", "intro": [], "sections": [{"title": "El valor de los casos reales", "paragraphs": [{"text": "La teoria esta bien. Los prompts son utiles. Pero nada ensena como ver como funciona en casos concretos, con sintomas reales, vehiculos reales y diagnosticos que luego se confirmaron en el taller.", "list": false}, {"text": "Este capitulo documenta 10 averias reales. Para cada una: el vehiculo, el sintoma exacto, el prompt utilizado, la respuesta del agente y lo que el taller encontro despues.", "list": false}], "subsections": [{"title": "CASO 1 - El VW Golf que no arrancaba en frio", "paragraphs": [{"text": "Vehiculo: VW Golf IV 1.9 TDI 2002, 198.000 km", "list": false}, {"text": "Sintoma: Arranque muy dificil en frio, 4-5 intentos, tirones primeros 30 segundos, peor en invierno.", "list": false}, {"text": "Diagnostico agente: 1a causa (Alta): bujias de precalentamiento desgastadas. 2a: perdida presion inyectores. 3a: sensor temperatura.", "list": false}, {"text": "Taller confirmo: Tres bujias al limite, una rota. Cambio completo: 95 EUR. Problema desaparecio.", "list": false}]}, {"title": "CASO 2 - El Renault Clio con vibracion a 110 km/h", "paragraphs": [{"text": "Vehiculo: Renault Clio III 1.2 gasolina 2009, 87.000 km", "list": false}, {"text": "Sintoma: Vibracion en volante entre 100-120 km/h. Hace 3 semanas cambio neumaticos traseros.", "list": false}, {"text": "Diagnostico agente: Desequilibrio en rueda trasera post-montaje. Responsabilidad del taller de neumaticos.", "list": false}, {"text": "Taller confirmo: Peso equilibrado despegado en trasera derecha. Reequilibrado sin coste.", "list": false}]}, {"title": "CASO 3 - El Ford Focus con consumo disparado", "paragraphs": [{"text": "Vehiculo: Ford Focus 1.6 TDCi 110cv 2011, 142.000 km", "list": false}, {"text": "Sintoma: Consumo subio de 5.8 a 7.5-8L/100km en 2 meses. Sin testigos.", "list": false}, {"text": "Diagnostico agente: 1a causa: filtro combustible saturado. 2a: sensor temperatura. 3a: inyectores.", "list": false}, {"text": "Taller confirmo: Filtro nunca cambiado en 142.000 km. Cambio: 65 EUR. Consumo volvio a 6.1L.", "list": false}]}, {"title": "CASO 4 - El Toyota Prius que perdia potencia", "paragraphs": [{"text": "Vehiculo: Toyota Prius III 2010, 178.000 km", "list": false}, {"text": "Sintoma: Perdida potencia progresiva en subidas. Autonomia electrica muy reducida.", "list": false}, {"text": "Diagnostico agente: Degradacion bateria de traccion. Verificar con app Dr. Prius. 4 modulos por debajo del 70%.", "list": false}, {"text": "Taller confirmo: Sustitucion 4 modulos defectuosos: 650 EUR. Potencia y autonomia recuperadas.", "list": false}]}, {"title": "CASO 5 - El Seat Leon con testigo ABS (Codigo C0035)", "paragraphs": [{"text": "Vehiculo: Seat Leon II 2.0 TDI 2007, 165.000 km", "list": false}, {"text": "Sintoma: Testigo ABS encendido permanente. Frenos parecen funcionar con normalidad.", "list": false}, {"text": "Diagnostico agente: Sensor ABS rueda delantera izquierda defectuoso. El coche puede conducirse en seco pero sin ABS activo.", "list": false}, {"text": "Taller confirmo: Sensor ABS defectuoso. Cambio: 75 EUR (pieza 38 + montaje 37). Testigo apagado.", "list": false}]}, {"title": "CASO 6 - El BMW 320d con humo azul al arrancar", "paragraphs": [{"text": "Vehiculo: BMW 320d E90 2.0 163cv 2006, 221.000 km", "list": false}, {"text": "Sintoma: Nube humo azul en arranque frio que desaparece en 10-15 segundos. 0.3L aceite cada 1.000 km.", "list": false}, {"text": "Diagnostico agente: Desgaste de sellos de valvulas. Consumo dentro del umbral aceptable. Reparacion costosa (600-1.200 EUR).", "list": false}, {"text": "Decision usuario: Decidio no reparar dado el kilometraje. Lleva aceite en el maletero, revisa cada 2.000 km. Estable 18 meses.", "list": false}]}, {"title": "CASO 7 - El Opel Astra con ruido al girar el volante", "paragraphs": [{"text": "Vehiculo: Opel Astra H 1.6 gasolina 2005, 134.000 km", "list": false}, {"text": "Sintoma: Crujido o clic al girar el volante lento, especialmente aparcando. Mas audible en frio.", "list": false}, {"text": "Diagnostico agente: Rotulas de direccion desgastadas. Verificacion: poner mano sobre rotulas mientras alguien gira de tope a tope.", "list": false}, {"text": "Taller confirmo: Rotula lado derecho con juego. Cambio + alineacion: 130 EUR. Ruido eliminado.", "list": false}]}, {"title": "CASO 8 - El Mercedes C220 CDI en modo emergencia", "paragraphs": [{"text": "Vehiculo: Mercedes C220 CDI W203 2004, 198.000 km", "list": false}, {"text": "Sintoma: Modo emergencia intermitente al acelerar fuerte. Codigos P0299 + P140C.", "list": false}, {"text": "Diagnostico agente: Fuga en manguito entre intercooler y mariposa. Verificar manguitos bajo presion alta antes del actuador VGT.", "list": false}, {"text": "Taller confirmo: Manguito con microfisura que se abria bajo presion maxima. Cambio: 80 EUR. Problema resuelto.", "list": false}]}, {"title": "CASO 9 - El Nissan Qashqai con vibracion al frenar", "paragraphs": [{"text": "Vehiculo: Nissan Qashqai 1.5 dCi 2013, 112.000 km", "list": false}, {"text": "Sintoma: Vibracion en pedal y volante al frenar desde mas de 80 km/h. Discos nuevos hace 18 meses.", "list": false}, {"text": "Diagnostico agente: Discos deformados. Posible rodaje incorrecto o frenada brusca con discos calientes.", "list": false}, {"text": "Taller confirmo: Discos con 0.08mm de variacion. Sustitucion por Brembo: 160 EUR. Sin problemas.", "list": false}]}, {"title": "CASO 10 - El Kia Sportage con bateria que no cargaba", "paragraphs": [{"text": "Vehiculo: Kia Sportage III 2.0 CRDi 2014, 89.000 km", "list": false}, {"text": "Sintoma: Bateria de 3 anos cuesta arrancar. En marcha: 13.1V (deberia ser 13.8-14.4V).", "list": false}, {"text": "Diagnostico agente: Alternador no carga correctamente. Tambien: verificar si la bateria instalada es AGM para el sistema start/stop.", "list": false}, {"text": "Taller confirmo: Bateria convencional en coche start/stop. Requeria AGM. Sustitucion: 180 EUR.", "list": false}]}]}, {"title": "Conclusion del capitulo", "paragraphs": [{"text": "Diez casos. En ocho de los diez, la primera causa identificada por el agente fue la correcta. En los otros dos, la orientacion fue hacia la causa real aunque no fue la primera de la lista.", "list": false}, {"text": "La leccion no es que el agente siempre acierta a la primera. La leccion es que un cliente informado con un diagnostico orientativo siempre consigue una resolucion mas rapida, mas barata y con menos friccion.", "list": false}, {"text": "Pregunta de reflexion  Alguno de estos diez casos te recuerda a algo que hayas vivido con tu propio coche? Que habria cambiado si hubieras tenido el agente en ese momento?", "list": false}], "subsections": []}]}, {"title": "CAPÍTULO 11Tu Taller Inteligente: 3 Agentes Coordinados", "intro": [], "sections": [{"title": "El taller que trabaja cuando tu duermes", "paragraphs": [{"text": "Son las 23:47 del domingo. Marcos cerro el taller hace cinco horas. Esta cenando con su familia.", "list": false}, {"text": "En ese momento, un cliente escribe en Telegram: Hola, mi coche ha empezado a hacer un ruido raro al frenar y manana tengo un viaje largo. Es peligroso seguir?", "list": false}, {"text": "En 8 segundos, sin que Marcos haga nada, su Agente de Diagnostico responde con las preguntas correctas, diagnostica el problema probable y deja al cliente con la informacion que necesita.", "list": false}, {"text": "El lunes por la manana, Marcos encuentra el resumen automatico: cliente, consulta, diagnostico, cita confirmada. El cliente llego informado. La cita duro 40 minutos.", "list": false}], "subsections": []}, {"title": "Los 3 agentes y lo que hace cada uno", "paragraphs": [], "subsections": [{"title": "Agente 1 - MecanicIA (Diagnostico)", "paragraphs": [{"text": "Canal: Bot Telegram disponible 24/7. Diagnostica sintomas, interpreta codigos OBD, da recomendaciones de urgencia. NO da diagnosticos definitivos ni presupuestos cerrados.", "list": false}]}, {"title": "Agente 2 - GestionIA (Comercial y citas)", "paragraphs": [{"text": "Canal: Bot WhatsApp Business. Recoge datos del cliente, explica servicios, genera presupuestos orientativos, enlaza al sistema de citas. NO entra en diagnostico tecnico.", "list": false}]}, {"title": "Agente 3 - AdminIA (Back-office)", "paragraphs": [{"text": "Canal: Chat privado con el dueno del taller. Resumenes diarios, seguimiento de clientes, alertas de consultas sin respuesta. NO interactua con clientes.", "list": false}]}]}, {"title": "Arquitectura del codigo", "paragraphs": [{"text": "mecanicia-bot/", "list": false}, {"text": "├── src/", "list": false}, {"text": "│   ├── bot.ts              <- Punto de entrada, todos los comandos", "list": false}, {"text": "│   ├── agent/", "list": false}, {"text": "│   │   └── prompt.ts       <- Prompt maestro del agente", "list": false}, {"text": "│   ├── services/", "list": false}, {"text": "│   │   └── claude.ts       <- Comunicacion con la API de Claude", "list": false}, {"text": "│   ├── handlers/", "list": false}, {"text": "│   │   └── setup.ts        <- Flujo configuracion del vehiculo", "list": false}, {"text": "│   ├── db/", "list": false}, {"text": "│   │   └── index.ts        <- Persistencia JSON", "list": false}, {"text": "│   └── types/", "list": false}, {"text": "│       └── index.ts        <- Tipos TypeScript", "list": false}, {"text": "├── data/                   <- Datos persistentes", "list": false}, {"text": "├── .env.example", "list": false}, {"text": "├── Dockerfile", "list": false}, {"text": "├── docker-compose.yml", "list": false}, {"text": "└── package.json", "list": false}], "subsections": []}, {"title": "Instalacion paso a paso", "paragraphs": [], "subsections": [{"title": "Requisitos previos", "paragraphs": [{"text": "Node.js 20 o superior instalado", "list": true}, {"text": "Una cuenta en Telegram", "list": true}, {"text": "Una API Key de Anthropic (console.anthropic.com)", "list": true}]}, {"title": "Paso 1 - Crear el bot en Telegram", "paragraphs": [{"text": "Abre Telegram y busca @BotFather", "list": true}, {"text": "Escribe /newbot", "list": true}, {"text": "Dale un nombre: MecanicIA (o el nombre de tu taller)", "list": true}, {"text": "Dale un username: mecanicia_bot (debe acabar en _bot)", "list": true}, {"text": "Copia el TOKEN que te da BotFather", "list": true}]}, {"title": "Paso 2 - Instalar y configurar", "paragraphs": [{"text": "cd mecanicia-bot", "list": false}, {"text": "npm install", "list": false}, {"text": "cp .env.example .env", "list": false}, {"text": "# Edita .env con tu TELEGRAM_TOKEN y ANTHROPIC_API_KEY", "list": false}]}, {"title": "Paso 3 - Arrancar en local", "paragraphs": [{"text": "npm run dev", "list": false}, {"text": "# Deberias ver:", "list": false}, {"text": "# MecanicIA Bot arrancado correctamente", "list": false}, {"text": "# Listo para diagnosticar vehiculos", "list": false}]}, {"title": "Paso 4 - Desplegar en VPS (produccion)", "paragraphs": [{"text": "scp -r mecanicia-bot/ usuario@tu-vps:/home/usuario/", "list": false}, {"text": "ssh usuario@tu-vps", "list": false}, {"text": "cd mecanicia-bot", "list": false}, {"text": "cp .env.example .env && nano .env", "list": false}, {"text": "docker compose up -d", "list": false}, {"text": "docker compose logs -f", "list": false}]}]}, {"title": "Comandos del bot", "paragraphs": [], "subsections": []}, {"title": "El coste real del sistema", "paragraphs": [{"text": "Pregunta de reflexion  Si este bot hubiera existido hace 3 anos, cuanto dinero habrias ahorrado en consultas de taller que resultaron ser algo sencillo? Esa cifra es exactamente el valor que este sistema tiene.", "list": false}], "subsections": []}]}, {"title": "CAPÍTULO 12El Futuro: Cuando el Motor Habla Solo", "intro": [], "sections": [{"title": "La llamada que nadie esperaba", "paragraphs": [{"text": "Era un miercoles por la tarde cuando el movil de Lucia vibro con un mensaje de Telegram. No era un cliente. No era un proveedor. Era su coche.", "list": false}, {"text": "Hola Lucia. Soy tu Peugeot 308 2023. He detectado que la presion del neumatico trasero derecho ha bajado un 18% en las ultimas 6 horas. Te recomiendo parar en la proxima gasolinera para revisarlo antes de entrar en autovia.", "list": false}, {"text": "Este escenario no es ciencia ficcion. Es tecnologia que existe hoy, con piezas que ya estan en el mercado, esperando a ser conectadas.", "list": false}], "subsections": []}, {"title": "Las tres olas del cambio", "paragraphs": [], "subsections": [{"title": "Primera ola - La que has aprendido en este libro", "paragraphs": [{"text": "El mecanico o el conductor usa IA de forma activa. Describe sintomas, pide diagnosticos, configura su agente. Es lo que has construido leyendo este libro. Ya eres parte de esta primera ola. Donde estamos: ahora mismo, 2025.", "list": false}]}, {"title": "Segunda ola - El coche conectado que informa solo", "paragraphs": [{"text": "Dispositivos como el OBDLink MX+ se conectan al puerto OBD de tu coche via Bluetooth y envian datos en tiempo real a una app en tu movil. La pieza que falta, que cualquier desarrollador puede construir hoy, es el puente entre esos datos y el agente IA.", "list": false}, {"text": "# Puente OBD -> MecanicIA (Python)", "list": false}, {"text": "import obd, anthropic, time", "list": false}, {"text": "client = anthropic.Anthropic()", "list": false}, {"text": "def leer_datos_obd():", "list": false}, {"text": "connection = obd.OBD()", "list": false}, {"text": "datos = {}", "list": false}, {"text": "for cmd in [obd.commands.RPM, obd.commands.COOLANT_TEMP,", "list": false}, {"text": "obd.commands.OIL_TEMP, obd.commands.ENGINE_LOAD]:", "list": false}, {"text": "resp = connection.query(cmd)", "list": false}, {"text": "if not resp.is_null():", "list": false}, {"text": "datos[cmd.name] = str(resp.value)", "list": false}, {"text": "return datos", "list": false}, {"text": "def analizar_con_ia(datos, historial):", "list": false}, {"text": "resp = client.messages.create(", "list": false}, {"text": "model='claude-sonnet-4-20250514',", "list": false}, {"text": "max_tokens=300,", "list": false}, {"text": "messages=[{'role':'user','content':f'Datos OBD: {datos}\\nHistorial: {historial}\\nHay anomalia? Si todo normal responde: OK'}]", "list": false}, {"text": ")", "list": false}, {"text": "texto = resp.content[0].text.strip()", "list": false}, {"text": "return None if texto == 'OK' else texto", "list": false}, {"text": "while True:", "list": false}, {"text": "datos = leer_datos_obd()", "list": false}, {"text": "alerta = analizar_con_ia(datos, mi_historial)", "list": false}, {"text": "if alerta:", "list": false}, {"text": "print(f'ALERTA: {alerta}')  # Aqui: enviar a Telegram", "list": false}, {"text": "time.sleep(30)", "list": false}]}, {"title": "Tercera ola - El gemelo digital del vehiculo", "paragraphs": [{"text": "Cada coche tendra su representacion digital completa en la nube: historial desde el primer kilometro, patrones de uso, desgaste proyectado de cada componente, prediccion de fallos con semanas de antelacion. Donde estamos: en implantacion en flotas comerciales. Accesible para talleres independientes: 2026-2028.", "list": false}]}]}, {"title": "Por que los mecanicos que dominen la IA tendran trabajo para siempre", "paragraphs": [{"text": "Hay un miedo legitimo en el sector: si la IA puede diagnosticar coches, necesitamos menos mecanicos?", "list": false}, {"text": "La respuesta es no. La IA diagnostica. No repara. Ningun modelo de lenguaje puede cambiar un embrague. Ningun agente puede apretar un tornillo de culata a 85 Nm. Lo que si hace la IA es eliminar el tiempo perdido en buscar informacion, atender consultas basicas, redactar presupuestos.", "list": false}, {"text": "Mas tiempo para trabajar porque el agente gestiona las consultas basicas.", "list": true}, {"text": "Diagnosticos mas rapidos porque tiene acceso instantaneo a informacion tecnica de cualquier modelo.", "list": true}, {"text": "Clientes mas satisfechos porque reciben respuesta inmediata, incluso fuera del horario.", "list": true}, {"text": "Diferenciacion real en un sector donde la mayoria todavia no usa estas herramientas.", "list": true}], "subsections": []}, {"title": "El mensaje final", "paragraphs": [{"text": "Empezamos este libro con un coche parado en el arcen, con lluvia, a 30 kilometros de casa.", "list": false}, {"text": "Con lo que has aprendido aqui, esa situacion ya no es la misma. Ahora tienes un agente que conoce tu coche, que recuerda su historial, que puede diagnosticar sintomas en segundos y que trabaja mientras duermes.", "list": false}, {"text": "La IA no va a reemplazar al buen mecanico. Va a eliminar al mal mecanico, al que no evoluciona, al que tarda mas de lo necesario en diagnosticar, al que no puede competir en informacion con un cliente que llego preparado.", "list": false}, {"text": "Tu motor siempre ha hablado.Ahora, por fin, tienes las herramientas para escucharle.", "list": false}, {"text": "Pregunta de reflexion  Cual es el primer paso concreto que vas a dar esta semana con lo que has aprendido en este libro? Escribelo. Ponle una fecha. Y hazlo.", "list": false}], "subsections": []}]}, {"title": "CAPÍTULO 13Como Utilizar Claude para Todo", "intro": [], "sections": [{"title": "Mas alla del motor", "paragraphs": [{"text": "Has llegado al final del libro sabiendo hacer algo que muy poca gente sabe todavia: usar la inteligencia artificial de forma precisa, contextualizada y practica para resolver problemas reales. Esa habilidad no se queda en el taller.", "list": false}, {"text": "El mismo razonamiento que aplicaste para diagnosticar tu motor funciona en cualquier area de tu vida: tu negocio, tu trabajo, tu salud, tus finanzas, tu formacion, tu familia.", "list": false}], "subsections": []}, {"title": "La estructura que lo cambia todo: ROL + CONTEXTO + TAREA + FORMATO", "paragraphs": [{"text": "ROL: Le dices a Claude quien es en esta consulta. Actua como abogado especializado en derecho laboral espanol.", "list": false}, {"text": "CONTEXTO: Le das tu situacion especifica. Tengo una empresa de 8 empleados en Asturias, sector servicios.", "list": false}, {"text": "TAREA: Le dices exactamente que quieres. Explicame mis derechos si me despiden sin causa justificada.", "list": false}, {"text": "FORMATO: Le dices como quieres la respuesta. Dame una lista de pasos ordenados.", "list": false}], "subsections": []}, {"title": "Claude para tu negocio o trabajo", "paragraphs": [], "subsections": [{"title": "Como asesor legal de primer nivel", "paragraphs": [{"text": "Actua como abogado especializado en [area del derecho] en Espana.", "list": false}, {"text": "Mi situacion: [describe con detalle].", "list": false}, {"text": "Necesito saber: [pregunta concreta].", "list": false}, {"text": "Explicame que dice la ley, cuales son mis opciones y que haria", "list": false}, {"text": "un abogado en mi situacion. Avisame si debo consultar a un", "list": false}, {"text": "profesional obligatoriamente.", "list": false}, {"text": "Funciona para: contratos de alquiler, despidos, reclamaciones de consumidor, obligaciones fiscales de autonomos, herencias.", "list": false}]}, {"title": "Como director financiero personal", "paragraphs": [{"text": "Actua como asesor financiero independiente sin conflicto de interes.", "list": false}, {"text": "Mi situacion: [ingresos, gastos, deudas, ahorros, edad].", "list": false}, {"text": "Mi objetivo: [que quiero conseguir en cuanto tiempo].", "list": false}, {"text": "Analiza mi situacion y dame un plan concreto.", "list": false}, {"text": "Se directo sobre lo que estoy haciendo mal.", "list": false}]}, {"title": "Como consultor de negocio", "paragraphs": [{"text": "Actua como consultor de estrategia con experiencia en [sector].", "list": false}, {"text": "Mi negocio: [descripcion: que hago, empleados, facturacion, mayor problema].", "list": false}, {"text": "Necesito que me ayudes a [objetivo concreto].", "list": false}, {"text": "Dame un analisis honesto y un plan de accion para los proximos 90 dias.", "list": false}]}]}, {"title": "Claude para tu salud y bienestar", "paragraphs": [], "subsections": [{"title": "Como medico de primer contacto", "paragraphs": [{"text": "Actua como medico de familia que tiene todo el tiempo del mundo.", "list": false}, {"text": "Mi situacion: [sintomas detallados: cuando empezaron, intensidad,", "list": false}, {"text": "que los mejora o empeora, otros sintomas, edad, condiciones previas].", "list": false}, {"text": "No te pido que me diagnostiques. Quiero entender que puede estar", "list": false}, {"text": "pasando, que deberia explicarle al medico y que preguntas hacerle.", "list": false}, {"text": "Es algo que puede esperar o deberia ir hoy?", "list": false}]}, {"title": "Como nutricionista y entrenador personal", "paragraphs": [{"text": "Actua como nutricionista deportivo y entrenador personal.", "list": false}, {"text": "Mis datos: [edad, peso, altura, actividad actual, objetivo].", "list": false}, {"text": "Restricciones: [alergias, tiempo disponible, equipamiento].", "list": false}, {"text": "Dame un plan completo adaptado a mi vida real, no al cliente ideal.", "list": false}]}]}, {"title": "Claude para aprender cualquier cosa", "paragraphs": [], "subsections": [{"title": "El tutor personal que se adapta a ti", "paragraphs": [{"text": "Quiero aprender [tema]. Mi nivel actual: [principiante / base / avanzado].", "list": false}, {"text": "Mi objetivo: [que quiero poder hacer cuando lo haya aprendido].", "list": false}, {"text": "Tengo [X horas por semana] para dedicarle.", "list": false}, {"text": "Aprendo mejor con [ejemplos practicos / teoria / proyectos reales].", "list": false}, {"text": "Disena un plan de aprendizaje personalizado y", "list": false}, {"text": "empieza ensenadome el primer concepto.", "list": false}]}, {"title": "Para preparar conversaciones dificiles", "paragraphs": [{"text": "Tengo que tener una conversacion dificil con [quien] sobre [tema].", "list": false}, {"text": "El contexto es: [explica la situacion con detalle].", "list": false}, {"text": "Ayudame a preparar como decirlo: que palabras usar, como empezar,", "list": false}, {"text": "como manejar las posibles reacciones.", "list": false}, {"text": "Despues, haz de [la otra persona] y practica conmigo la conversacion.", "list": false}]}]}, {"title": "Los 10 prompts universales que deberias guardar", "paragraphs": [], "subsections": [{"title": "1. El explicador universal", "paragraphs": [{"text": "Explicame [concepto] como si tuviera [10 anos / ninguna base].", "list": false}, {"text": "Usa ejemplos de [mi sector / mi vida cotidiana].", "list": false}]}, {"title": "2. El revisor honesto", "paragraphs": [{"text": "Aqui esta [mi trabajo]. Se brutalmente honesto.", "list": false}, {"text": "Dime que esta mal antes de decirme que esta bien.", "list": false}]}, {"title": "3. El planificador de 90 dias", "paragraphs": [{"text": "Mi objetivo para los proximos 90 dias: [objetivo concreto y medible].", "list": false}, {"text": "Dame un plan semana a semana con acciones concretas, no principios.", "list": false}]}, {"title": "4. El analizador de opciones", "paragraphs": [{"text": "Tengo que elegir entre [opcion A] y [opcion B].", "list": false}, {"text": "Dame una tabla comparativa honesta y dime cual elegirías tu y por que.", "list": false}]}, {"title": "5. El generador de preguntas", "paragraphs": [{"text": "Voy a [reunion / entrevista / consulta medica] sobre [tema].", "list": false}, {"text": "Cuales son las 10 preguntas mas importantes que deberia hacer?", "list": false}]}, {"title": "6. El resumidor ejecutivo", "paragraphs": [{"text": "Aqui esta [documento largo]. Dame: los 3 puntos mas importantes,", "list": false}, {"text": "lo que debo hacer, y lo que deberia preocuparme. Maximo 10 lineas.", "list": false}]}, {"title": "7. El generador de ideas", "paragraphs": [{"text": "Dame 10 ideas obvias primero.", "list": false}, {"text": "Luego 5 ideas que nadie daria. No me filtres nada por si parece raro.", "list": false}]}, {"title": "8. El coach de habitos", "paragraphs": [{"text": "Quiero [habito]. He intentado [lo que ya probaste] y no ha funcionado", "list": false}, {"text": "porque [razon real]. Dame un sistema que se adapte a quien realmente soy.", "list": false}]}, {"title": "9. El abogado del diablo", "paragraphs": [{"text": "Estoy pensando en [accion importante].", "list": false}, {"text": "Actua como el abogado del diablo.", "list": false}, {"text": "Dime todo lo que puede salir mal y los riesgos que no estoy viendo.", "list": false}]}, {"title": "10. El sparring de conversaciones", "paragraphs": [{"text": "Tengo que hablar con [quien] sobre [tema dificil].", "list": false}, {"text": "Ayudame a preparar como decirlo. Luego haz de [esa persona]", "list": false}, {"text": "y practica conmigo la conversacion.", "list": false}]}]}, {"title": "El error mas frecuente con Claude", "paragraphs": [{"text": "Tratar a Claude como un buscador. Un buscador da resultados sobre preguntas simples. Claude razona sobre problemas complejos.", "list": false}, {"text": "Pregunta de buscador: Cual es la capital de Francia?", "list": false}, {"text": "Pregunta de Claude: Estoy pensando en mudarme a Francia con mi familia. Tenemos dos hijos en edad escolar y mi pareja trabaja en remoto. Que ciudades deberiamos considerar y por que? Cuales son los errores mas frecuentes de los espanoles que se mudan a Francia?", "list": false}, {"text": "El que sabe usar Claude bien no lo trata como una herramienta. Lo trata como el asesor mas inteligente y disponible que jamas ha tenido.", "list": false}], "subsections": []}, {"title": "El principio final", "paragraphs": [{"text": "Has llegado al ultimo capitulo de un libro sobre mecanica e inteligencia artificial. Y acabas de leer una seccion sobre nutricion, contratos de alquiler, conversaciones dificiles e inversiones.", "list": false}, {"text": "No es una contradiccion. Es la naturaleza de la herramienta.", "list": false}, {"text": "La mecanica fue la puerta de entrada. Lo que hay al otro lado es mucho mas grande.", "list": false}, {"text": "Pregunta de reflexion  Fuera de la mecanica, cual es el area de tu vida donde mas tiempo o dinero pierdes por falta de informacion o de un buen asesor? Ese es el siguiente agente que deberias construir.", "list": false}], "subsections": []}]}, {"title": "Apendice A - Prompt Maestro Completo v2.0", "intro": [{"text": "Copia este prompt, personaliza los campos entre corchetes con tus datos reales y pegalo en Claude para activar tu agente personalizado.", "list": false}, {"text": "═══════════════════════════════════════", "list": false}, {"text": "MECANICA IA - PROMPT MAESTRO v2.0", "list": false}, {"text": "Libro La IA y Mi Motor", "list": false}, {"text": "═══════════════════════════════════════", "list": false}, {"text": "Eres MecanicIA, un agente especializado en diagnostico,", "list": false}, {"text": "mantenimiento y reparacion de vehiculos de motor.", "list": false}, {"text": "Actuas como un mecanico senior con 25 anos de experiencia", "list": false}, {"text": "en mecanica tradicional y diagnosis electronica moderna.", "list": false}, {"text": "PERFIL DEL VEHICULO ASIGNADO:", "list": false}, {"text": "Propietario: [TU NOMBRE]", "list": false}, {"text": "Marca y modelo: [MARCA MODELO]", "list": false}, {"text": "Ano de fabricacion: [ANO]", "list": false}, {"text": "Motor/Version: [EJ: 1.9 TDI 105CV / 1.4 TSI 125CV]", "list": false}, {"text": "Tipo de combustible: [Diesel / Gasolina / Hibrido / Electrico]", "list": false}, {"text": "Transmision: [Manual / Automatica / CVT]", "list": false}, {"text": "Kilometros actuales: [KM]", "list": false}, {"text": "Uso principal: [Ciudad / Mixto / Carretera / Autopista]", "list": false}, {"text": "HISTORIAL CONOCIDO DEL VEHICULO:", "list": false}, {"text": "- [Correa distribucion: cambiada a X km o sin historial]", "list": false}, {"text": "- [Aceite: cambio hace X km, tipo aceite]", "list": false}, {"text": "- [Pastillas delanteras: X km]", "list": false}, {"text": "- [Pastillas traseras: X km]", "list": false}, {"text": "- [Bateria: X anos]", "list": false}, {"text": "- [Filtro aire: desconocido]", "list": false}, {"text": "- [Neumaticos: X meses]", "list": false}, {"text": "- [Fallos conocidos: descripcion]", "list": false}, {"text": "CUANDO TE CONSULTEN UN PROBLEMA:", "list": false}, {"text": "1. Haz entre 2 y 4 preguntas clave antes de diagnosticar", "list": false}, {"text": "2. Ordena causas de mayor a menor frecuencia", "list": false}, {"text": "3. Indica verificaciones de facil/barato a complejo/caro", "list": false}, {"text": "4. Indica si el coche es seguro para seguir usando", "list": false}, {"text": "5. Da estimacion del coste en Espana", "list": false}, {"text": "CUANDO TE DEN UN CODIGO OBD:", "list": false}, {"text": "1. Explica que significa en lenguaje simple", "list": false}, {"text": "2. Lista causas probables para ESTE motor en concreto", "list": false}, {"text": "3. Indica cuales puede verificar el usuario y cuales necesitan taller", "list": false}, {"text": "4. Senala si es urgente o puede esperar", "list": false}, {"text": "FORMATO DE RESPUESTA:", "list": false}, {"text": "DIAGNOSTICO PRELIMINAR", "list": false}, {"text": "[Tu analisis inicial]", "list": false}, {"text": "NECESITO SABER (solo si hace falta)", "list": false}, {"text": "[Preguntas para afinar]", "list": false}, {"text": "CAUSAS PROBABLES (de mas a menos frecuente)", "list": false}, {"text": "1. [Causa] - Probabilidad: Alta/Media/Baja", "list": false}, {"text": "2. [Causa] - Probabilidad: Alta/Media/Baja", "list": false}, {"text": "PASOS A SEGUIR", "list": false}, {"text": "Paso 1: [Lo mas facil/barato]", "list": false}, {"text": "Paso 2: [Verificacion intermedia]", "list": false}, {"text": "Paso 3: [Si todo falla: taller]", "list": false}, {"text": "URGENCIA", "list": false}, {"text": "Verde: puede esperar / Naranja: esta semana / Rojo: no conducir", "list": false}, {"text": "COSTE ESTIMADO EN ESPANA", "list": false}, {"text": "Pieza: X-Y EUR | Mano de obra: X-Y EUR | Total: X-Y EUR", "list": false}, {"text": "═══════════════════════════════════════", "list": false}, {"text": "Soy un agente IA. Para diagnosticos definitivos,", "list": false}, {"text": "consulta siempre a un mecanico profesional.", "list": false}], "sections": []}, {"title": "Apendice B - Los 50 Codigos OBD mas Comunes", "intro": [{"text": "Referencia rapida. Para diagnostico completo usa el prompt del Capitulo 3 con tu vehiculo especifico.", "list": false}, {"text": "Urgencia: Verde = sin urgencia / Amarillo = revisar pronto / Naranja = esta semana / Rojo = no conducir", "list": false}], "sections": []}, {"title": "Apendice C - Recursos, Herramientas y Lectores OBD", "intro": [], "sections": [{"title": "Adaptadores OBD recomendados 2025", "paragraphs": [], "subsections": []}, {"title": "Apps recomendadas", "paragraphs": [], "subsections": []}, {"title": "Herramientas basicas para el conductor", "paragraphs": [], "subsections": []}, {"title": "Webs de recambios en Espana", "paragraphs": [{"text": "autodoc.es - Catalogo amplio, filtrado por matricula, buen precio", "list": true}, {"text": "mister-auto.es - OEM de marca a buen precio, envio rapido", "list": true}, {"text": "recambioscoche.es - Buena seleccion nacional", "list": true}, {"text": "ebay.es/motor - Segunda mano y piezas especificas", "list": true}], "subsections": []}, {"title": "Para seguir aprendiendo", "paragraphs": [{"text": "Canal YouTube ScannerDanner (ingles) - El mejor del mundo en diagnosis electronica avanzada", "list": true}, {"text": "Canal YouTube EV Puzzle - Vehiculos electricos en espanol", "list": true}, {"text": "docs.anthropic.com - Documentacion oficial de Claude, actualizada constantemente", "list": true}, {"text": "claude.ai - Para usar el agente directamente desde el navegador o movil", "list": true}], "subsections": []}]}, {"title": "Apendice D - Glosario IA + Mecanica", "intro": [{"text": "Agente IA", "list": false}, {"text": "Sistema de inteligencia artificial configurado con un rol, contexto y forma de trabajar especificos. A diferencia de un chatbot generico, el agente sabe quien es y como debe responder en su dominio.", "list": false}, {"text": "Arbol de levas", "list": false}, {"text": "Eje rotativo que controla la apertura y cierre de las valvulas del motor. En motores con distribucion variable (VVTI, Valvetronic) su posicion puede ajustarse electronicamente.", "list": false}, {"text": "Ciguenal", "list": false}, {"text": "El eje principal del motor que convierte el movimiento lineal de los pistones en movimiento rotativo.", "list": false}, {"text": "Claude", "list": false}, {"text": "El modelo de inteligencia artificial desarrollado por Anthropic. Disponible en claude.ai, gratuito para uso basico.", "list": false}, {"text": "Common rail", "list": false}, {"text": "Sistema de inyeccion diesel de alta presion donde todos los inyectores comparten un rail de combustible a 1.600-2.500 bares.", "list": false}, {"text": "Correa de distribucion", "list": false}, {"text": "Correa dentada que sincroniza el ciguenal con los arboles de levas. Su rotura en motores de interferencia provoca dano catastrofico.", "list": false}, {"text": "DPF/FAP", "list": false}, {"text": "Filtro de particulas diesel. Captura el hollin del escape y lo quema periodicamente mediante regeneracion.", "list": false}, {"text": "ECU/PCM", "list": false}, {"text": "Unidad de control electronico del motor. El cerebro del motor que gestiona la inyeccion, el encendido y todos los parametros.", "list": false}, {"text": "EGR", "list": false}, {"text": "Valvula de recirculacion de gases de escape. Devuelve parte de los gases a la admision para reducir emisiones de NOx.", "list": false}, {"text": "GDI", "list": false}, {"text": "Inyeccion directa de gasolina. El combustible se inyecta directamente en el cilindro, no en el colector. Mas eficiente pero propenso a depositos de carbono.", "list": false}, {"text": "Hidraulicos de valvulas", "list": false}, {"text": "Pequenos cilindros hidraulicos que ajustan automaticamente la holgura de las valvulas. Su ruido en frio suele indicar aceite degradado.", "list": false}, {"text": "Inyector", "list": false}, {"text": "Componente que introduce el combustible en el cilindro a alta presion en el momento exacto determinado por la ECU.", "list": false}, {"text": "Junta de culata", "list": false}, {"text": "Junta de estanqueidad entre el bloque del motor y la culata. Su rotura permite que el agua del circuito de refrigeracion entre al motor.", "list": false}, {"text": "LLM", "list": false}, {"text": "Large Language Model. El tipo de inteligencia artificial que esta detras de Claude y otros asistentes. Aprende de grandes cantidades de texto y puede razonar y responder en lenguaje natural.", "list": false}, {"text": "MAF", "list": false}, {"text": "Sensor de masa de aire (Mass Air Flow). Mide la cantidad de aire que entra al motor para calcular la inyeccion correcta.", "list": false}, {"text": "Misfire", "list": false}, {"text": "Fallo de encendido en uno o mas cilindros. El combustible entra pero no se quema correctamente. Genera codigos P030x.", "list": false}, {"text": "OBD-II", "list": false}, {"text": "Sistema de diagnostico a bordo de segunda generacion. Puerto estandar en todos los vehiculos desde 1996 (gasolina) y 2001 (diesel) en Europa.", "list": false}, {"text": "Prompt", "list": false}, {"text": "Las instrucciones o preguntas que le das a la IA. La calidad del prompt determina directamente la calidad de la respuesta.", "list": false}, {"text": "Prompt Maestro", "list": false}, {"text": "Conjunto amplio de instrucciones que define el rol, contexto y comportamiento de un agente IA.", "list": false}, {"text": "Sensor lambda/sonda lambda", "list": false}, {"text": "Sensor en el escape que mide el oxigeno de los gases. Informa a la ECU sobre si la mezcla aire-combustible es correcta.", "list": false}, {"text": "Silent-block", "list": false}, {"text": "Casquillo de goma y metal que une componentes de la suspension amortiguando vibraciones. Se desgasta y genera ruidos y holguras.", "list": false}, {"text": "SOH", "list": false}, {"text": "Estado de salud (State of Health) de una bateria de traccion. Porcentaje de capacidad original conservada.", "list": false}, {"text": "Tensor de cadena", "list": false}, {"text": "Componente que mantiene la tension correcta en la cadena de distribucion. Su desgaste genera ruido metalico tipico en arranque en frio.", "list": false}, {"text": "Turbo VGT/VNT", "list": false}, {"text": "Turbocompresor de geometria variable. Las paletas cambian de angulo para optimizar la presion a diferentes RPM.", "list": false}, {"text": "Volante bimasa", "list": false}, {"text": "Sistema de amortiguacion de vibraciones entre el motor y la caja de cambios. Habitual en diesel modernos. Pieza cara cuando falla.", "list": false}, {"text": "* * *", "list": false}, {"text": "Tu motor siempre ha hablado.", "list": false}, {"text": "Ahora, por fin,", "list": false}, {"text": "tienes las herramientas para escucharle.", "list": false}, {"text": "asesoriacastresana.com", "list": false}], "sections": []}];
